INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'Sucedeu que, depois da morte de Saul, Davide voltou da derrota dos Amalecitas e esteve dois dias em Siceleg.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'Ao terceiro dia, apareceu um homem, que vinha do campo de Saul, com a roupa rasgada e a cabeça coberta de pó. Logo que chegou a Davide, prostrou-se com o rosto em terra, fazendo-lhe um a profunda reverência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'Davide disse-lhe: Donde vens? Ele respondeu-lhe: Eu salvei-me do acampamento de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'Davide disse-lhe: O que aconteceu? Dize-mo. Ele respondeu: O povo fugiu da batalha, muitos do povo caíram mortos, e até Saul e seu filho Jónatas pereceram'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'Davide disse ao jovem que lhe dava esta nova: Como sabes tu que Saul e Jónatas, seu filho, morreram?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'O jovem, que lhe dava a notícia, respondeu: Fui, casualmente, ao monte de Gelboé, e encontrei Saul que se apoiava sobre a sua lança, quando carros e cavaleiros se aproximavam dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'Olhando para trás e vendo-me, chamou-me. Tendo-lhe eu respondido: Aqui me tens'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'perguntou-me: Quem és tu? Eu respondi-lhe: Sou um Amalecita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'Ele disse-me: Lança-te sobre mim e mata-me, porque estou muito angustiado, e toda a minha vida está ainda em mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'Lançando-me sobre ele, matei-o, porque via que ele não podia viver depois da derrota; tomei o diadema, que tinha na cabeça, e o bracelete do braço, e aqui o trouxe a ti, meu Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'Davide, porém, apanhando as suas vestes, as rasgou e (igualmente) todos os homens que estavam com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Fizeram pranto, chorando e jejuando, até a tarde por Saul e Jónatas, seu filho, pelo povo do Senhor e pela casa de Israel, porque tinha perecido à espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'Davide disse ao jovem que lhe trouxera a notícia: Donde és tu? Ele respondeu-lhe: Sou filho dum homem estrangeiro Amalecita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'Davide disse-lhe: como não temeste estender a mão para matar o ungido do Senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'Davide (então), chamando um dos seus criados, disse-lhe: Vem cá, lança-te sobre esse homem. Ele feriu o amalecita, que morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'Davide disse-lhe: O teu sangue (caia) sobre a tua cabeça, porque a tua própria boca falou contra ti, ao dizer: Eu matei o ungido do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'Então Davide compôs este cântico fúnebre sobre Saul e sobre Jónatas, seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'e ordenou que o ensinassem aos filhos de Judá. É o Cântico do Arco, e está escrito no livro do Justo: (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'A tua glória, Israel, pereceu sobre os teus montes. Como caíram os heróis?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Não o noticies em Get, nem o publiqueis nas ruas de Ascalon, para que não se alegrem as filhas dos Filisteus, não exultem as filhas dos incircuncidados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'ó montes de Gelboé, nem orvalho, nem chuva caiam sobre vós; nem haja campos de (que oferecer) primícias, porque lá foi lançado por terra o escudo dos fortes, o escudo de Saul, como se não tivesse sido ungido com óleo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'Sem sangue de mortos, sem gordura de fortes, o arco de Jónatas nunca voltou para trás, e a espada de Saul nunca se retirou em vão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'Saul e Jónatas, amáveis e belos na sua vida, também na morte se não separaram. Eram mais ligeiros do que as águias, mais valentes do que os leões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, 'Filhas de Israel, chorai sobre Saul, que vos vestia de púrpura entre as delícias, e que vos dava os ornamentos de ouro para vosso enfeite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'Como foi morto Jónatas sobre os teus montes? Como caíram os fortes no combate?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'Choro por ti, ó meu irmão Jónatas, que eras para mim tão querido! A tua amizade era mais preciosa para mim que o amor das mulheres!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'Como caíram os heróis? Como pereceram os fortes guerreiros!');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Depois disto Davide consultou o Senhor, dizendo: Irei eu para alguma das cidades de Judá? O Senhor respondeu-lhe: Vai. Davide disse: Para onde irei? O Senhor respondeu-lhe: Para Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'Foi, pois, Davide com as suas duas mulheres, Aquinoão de Jezrael, e Abigail, viúva de Nabal do Carmelo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Levou também a gente que estava com ele, cada um com a sua família, ficando todos a morar nas povoações de Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Vieram os homens de Judá, e ungiram ali Davide, para reinar sobre a casa de Judá. Soube Davide que os homens de Jabes de Galaad tinham sepultado Saul;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'e enviou mensageiros aos homens de Jabes de Galaad, a dizer-lhes: Bem-ditos sejais do Senhor, vós que praticastes esta obra de misericórdia com Saul, vosso senhor, dando-lhe sepultura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Agora o Senhor vos recompensará certamente segundo a sua misericórdia e verdade. Eu também vos agradecerei esta acção que fizestes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'Cobrem alento as vossas mãos, sede fortes, porque, ainda que tenha morrido Saul, vosso senhor, a casa de Judá ungiu-me por seu rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Abner, porém, filho de Ner, general do exército de Saul tomou Isboset, filho de Saul, levou-o por todo o acampamento'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'e constituiu-o rei sobre Galaad, sobre Gessuri, sobre Jezrael, sobre Efraim, sobre Benjamim e sobre todo o Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'Isboset, filho de Saul, tinha quarenta anos, quando começou a reinar em Israel, e reinou dois anos. Só a casa de Judá seguiu Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'O tempo que Davide reinou, em Hebron, sobre a casa de Judá, foi de sete anos e seis meses.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Abner, filho de Ner, com a gente de Isboset, filho de Saul, saiu do acampamento e foi para Gabaon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'Joab, filho de Sarvia, e os homens de Davide, saíram e encontraram-se com eles perto da piscina de Gabaon. Tendo-se aproximado, acamparam uns dum lado da piscina, e outros do outro lado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'Abner disse a Joab: Saiam alguns jovens, e escaramucem diante de nós. Joab respondeu: Saiam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Levamtaram-se e avançaram, em número igual, doze de Benjamim, por parte de Isboset, filho de Saul, e doze da gente de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Cada um (destes) tomando pela cabeça o seu opositor, enterrou a espada no costado do seu contrário, e morreram (todos) ao mesmo tempo. Por isso foi dado àquele lugar o nome de Campo dos valentes de Gabaon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Seguiu-se uma crua batalha naquele dia, e Abner e os homens de Israel foram postos em fuga pelas tropas de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'Estavam ali os três filhos de Sarvia, Joab, Abisai e Asael. Asael era muito ligeiro na carreira, como uma gazela selvagem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, '(Ora) Asael perseguia Abner, e não declinava nem para a direita nem para a esquerda, correndo incessantemente atrás dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Abner voltou-se para trás e disse: Tu não és Asael? Ele respondeu: Sou eu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Abner disse-lhe: Vai para a direita ou para a esquerda, apanha algum desses jovens, e toma os seus despojos. Mas Asael não quis deixar de o perseguir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Abner disse outra vez a Asael: Retira-te, não me sigas, para que eu não me veja obrigado a atravessar-te, e não possa eu mais aparecer diante de teu irmão Joab.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, 'Asael desprezou ouvi-lo e não quis desviar-se. Então Abner feriu-o no ventre com a parte inferior da lança, saindo a lança por trás. Morreu ali mesmo, onde caiu. Todos os que passavam por aquele lugar, em que Asael caíra morto, paravam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'Enquanto Joab e Abisai seguiam Abner, que ia fugindo, pôs-se o sol, ao chegarem ao outeiro do aqueduto, que está defronte do vale, sobre o caminho do deserto de Gabaon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 25, 'Os filhos de Benjamim uniram-se com Abner, e, cerrados num batalhão, fizeram alto no cimo de um cabeço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 26, 'Abner, gritando a Joab, disse: Não se saciará de sangue a tua espada? Ignoras porventura que, no fim, vem a desesperação? Para quando guardas dizer ao povo que deixe de perseguir seus irmãos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 27, 'Joab respondeu: Viva o Senhor, que se não tivesses falado, o povo não deixaria de perseguir seus irmãos, antes de amanhã, de manhã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 28, 'Joab tocou a trombeta, e todo o exército fez alto; não perseguiram mais Israel, nem travaram mais combate.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 29, 'Abner e os seus caminharam pela planície toda aquela noite, passaram o Jordão e, percorrido todo o país de Bet-horon, chegaram ao seu acampamento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 30, 'Joab, tendo desistido de perseguir Abner, voltando para trás, juntou todo o povo. Da gente de Davide faltaram dezanove homens, sem contar Asael.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 31, 'Os soldados de Davide tinham ferido, dos de Benjamim e dos que estavam com Abner, trezentos e setenta homens, que morreram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 32, 'Tomaram (o corpo de) Asael e enterraram-no na sepultura de seu pai em Belém. Marcharam, toda a noite, Joab e os homens que estavam com ele, e ao raiar do dia chegaram a Hebron.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Houve uma longa guerra entre a casa de Saul e a casa de Davide, adiantando-se Davide e fortificando-se cada vez mais, enquanto que a casa de Saul decaía todos os dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Nasceram filhos a Davide em Hebron. O seu primogênito foi Amnon, (que teve) de Aquinoão Jezraelita;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'depois deste, (teve) Queleab de Abigail, viúva de Nabal do Carmelo; o terceiro foi Absalão, filho de Maaca, filha de Tolmai, rei de Gessur;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'O quarto foi Adonias, filho de Hagit; o quinto foi Safatia, filho de Abital;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'o sexto Jetraão, filho de Elga, mulher de Davide. Estes (filhos) nasceram a Davide em Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'Continuando a guerra entre a casa de Saul e a casa de Davide, Abner, filho de Ner, governava a casa de Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'Saul tinha tido uma mulher secundária, chamada Resfa, filha de Aia. Isboset disse a Abner:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'Por que te juntaste tu à mulher secundária de meu pai? Ele, em extremo irado por estas palavras de Isboset, disse; Porventura sou eu (desprezível) como a cabeça de um cão, eu que sou hoje o adversário de Judá, que usei de piedade com a casa de Saul, teu pai, com seus irmãos e parentes, e que te não entreguei nas mãos de Davide? E tu buscas hoje em mim motivo para me arguires a propósito desta mulher?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Deus trate a Abner com toda a sua severidade, se eu não procurar para Davide o que o Senhor lhe prometeu com juramento,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'fazendo que o reino seja transferido da casa de Saul, e que o trono de Davide seja elevado sobre Israel e sobre Judá, desde Dan até Bersabee.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, '(Isboset) não lhe pode responder coisa alguma, porque o temia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Abner enviou mensageiros a Davide, que da sua parte lhe disseram; A quem pertence o país? E que acrescentassem: Faze amizade comigo, e eu te ajudarei a voltar para ti todo o Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Davide respondeu: óptimo; eu farei amizade contigo, mas peço-te um a coisa: que não me venhas ver, sem me trazeres contigo Micol, filha de Saul; deste modo virás, e me verás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'Davide enviou mensageiros a Isboset, filho de Saul, a dizer-lhe: Restitue-me Micol, minha mulher, que eu desposei por ter matado cem Filisteus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'Isboset mandou tirá-la ao seu (segundo) marido, Faltiel, filho de Lais,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'e o seu (segundo) marido a seguia chorando até Baurim. Abner disse-lhe: Vai, e volta para trás. E ele voltou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'Começou Abner a tratar com os anciães de Israel, dizendo: Muito tempo há que vós desejáveis que Davide reinasse sobre vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Fazeio-o, pois, agora, porque o Senhor disse a Davide: Eu salvarei por meio do meu servo o meu povo de Israel da mão dos Filisteus e de todos os seus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'Do mesmo modo falou Abner aos de Benjamim, e, a seguir, foi ter com Davide em Hebron para lhe dizer tudo o que os de Israel e todos os de Benjamim tinham resolvido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'Abner apresentou-se a Davide em Hebron, com vinte homens. Davide deu um banquete a Abner e aos homens que tinham ido com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Abner disse a Davide: Eu Irei para reunir a ti, meu senhor e rei, todo o Israel, e farei aliança contigo, para que reines sobre todos, como deseja o teu coração. Tendo David e despedido Abner, e tendo-se este ido em paz,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'chegaram logo os homens de Davide e Joab, os quais, tendo matado uns ladrões, traziam uma grande presa. Abner, porém, já não estava com Davide em Hebron, porque o tinha despedido, e ele tinha-se retirado em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'Joab, com todo o exército que estava com ele, chegou depois; não faltou, porém, quem dissesse a Joab: Abner, filho de Ner, veio ter com o rei, e este o despediu, e ele foi-se em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'Joab foi ter com o rei e disse: Que fizeste? Abner acaba de vir ter contigo; por que o despediste e o deixaste retirar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 25, 'Tu não sabes que Abner, filho de Ner, veio ter contigo para te enganar, para saber as tuas saídas e as tuas entradas e para sondar tudo quanto fazes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 26, 'Joab logo que saiu de junto de Davide, enviou mensageiros atrás de Abner, e o fez voltar da cisterna de Sira, sem Davide o saber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 27, 'Voltando Abner a Hebron, Joab chamou-o à parte, dentro da porta, como para lhe falar em segredo, e aí mesmo o feriu no ventre e matou, para vingar o sangue de Asael, seu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 28, 'Ouvindo Davide o que tinha acontecido, disse: Eu e o meu reino, para sempre estamos inocentes, diante do Senhor, do sangue de Abner, filho de Ner.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 29, 'Ele caia sobre a cabeça de Joab e sobre toda a casa de seu pai, e nunca falte na casa de Joab quem padeça de gonorreia, quem seja leproso, quem pegue no fuso, quem seja morto à espada e quem esteja privado de pão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 30, 'Joab e Abisai, seu Irmão, mataram Abner, porque ele tinha morto (em legitima defesa) seu irmão Asael na batalha de Gabaon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 31, 'Davide disse a Joab e a todo o povo, que estava com ele; Rasgai as vossas vestes, cobri-vos de saco e chorai nos funerais de Abner. O rei Davide ia atrás do féretro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 32, 'Logo que sepultaram Abner em Hebron, o rei Davide levantou a voz e chorou sobre a sepultura de Abner, chorando também todo o povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 33, 'O rei, pranteando Abner, cantou assim: Abner não morreu como costumam morrer os cobardes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 34, 'As tuas mãos não foram atadas, nem os teus pés carregados de grilhões, mas tu caíste, como se cai diante dos filhos da iniquidade. Todo o povo, repetindo o mesmo, chorou sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 35, 'Todo o povo se acercou de Davide, para que ele tomasse algum alimento, antes de findar o dia, mas ele jurou: Deus me trate com todo o rigor, se eu provar pão ou o quer que seja, antes do sol posto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 36, 'Todo o povo ouviu e achou bem, como achava bem tudo o que o rei fazia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 37, 'E todo o povo, todo o Israel, reconheceu naquele dia que o rei não tivera parte alguma no assassinato de Abner, filho de Ner.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 38, 'O rei disse ao seus servos: Não sabeis que um chefe, um grande homem, caiu hoje em Israel?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 39, 'Eu, embora ungido rei, sou brando; estes homens, filhos de Sarvia, são mais duros que eu. O Senhor dê, a quem faz mal, segundo a sua malícia.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Quando Isboset, filho de Saul, soube que Abner tinha sido morto em Hebron, perdeu a força de suas mãos, e todo o Israel ficou perturbado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'Tinha o filho de Saul a seu serviço dois capitães de ladrões, um dos quais se chamava Baana, e outro Recab, filhos de Remon de Berot, da tribo de Benjamim, pois Berot era contada (entre as cidades) de Benjamim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'Os Berotitas haviam fugido para Getaim, e moraram lá com o forasteiros até àquele tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Jónatas, filho de Saul, tinha um filho aleijado dos pés, porque, aos cinco anos, quando chegou de Jezrnel a nova (da morte) de Saul e de Jónatas, sua ama, tomando-o e fugindo, na precipitação da fuga o deixou cair, e, assim ele ficou coxo. Chamava-se Mifiboset.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'Vindo os filhos de Remon, Berotita, Recab e Baana, entraram em casa de Isboset no maior calor do dia. Ele estava no seu leito, dormindo a sesta. A porteira da casa, estando a limpar trigo, tinha adormecido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'Entraram, pois, na casa sem ser sentidos, Recab e Baana, a tomar umas espigas de trigo; feriram Isboset no ventre e fugiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Quando eles entraram em casa, Isboset dormia em cima do seu leito no quarto; ferindo-o, mataram-no e, cortando-lhe a cabeça, andaram toda a noite pelo caminho do deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Levaram a cabeça de Isboset a Davide, a Hebron, e disseram ao rei: Eis a cabeça de Isboset, filho de Saul, teu inimigo, que procurava tirar-te a vida. O Senhor vingou hoje o rei, meu senhor, de Saul e da sua linhagem'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Todavia Davide, respondendo a Recab e a Baana, seu irmão, filhos de Remon Berotlta, disse-lhe: Viva o Senhor, que livrou a minha alma de toda a angústia!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'Àquele que me anunciou: Morreu Saul cuidando que me trazia uma boa nova, fiz que o prendessem e matassem em Siceleg, quando ele julgava ter merecido alvíçaras pela nova;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'quanto mais agora que homens malvados mataram um homem Inocente dentro da sua casa, sobre o seu leito, não vingarei eu o sangue derramado pelas vossas mãos, exterminando-vos da terra?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'Davide deu ordem aos seus criados e eles os mataram e, cortando-lhes as mãos e os pés, penduraram-nos sobre a piscina de Hebron. Depois, tomando a cabeça de Isboset, sepultaram-na do sepulcro de Abner, em Hebron.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Todas as tribos de Israel foram ter com Davide a Hebron, dizendo: Aqui nos tens, somos teus ossos e tua carne (porque descendemos todos de Jacob).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Ainda quando Saul era rei sobre nós, já eras tu o que conduzias e reconduzias Israel. Demais, o Senhor disse-te: Tu apascentarás o meu povo de Israel, serás condutor de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Foram também os anciães de Israel ter com o rei a Hebron, e ali o rei Davide fez aliança com eles diante do Senhor, e eles ungiram Davide rei sobre Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'Davide tinha trinta anos, quando começou a reinar, e reinou quarenta anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Reinou, em Hebron, sete anos e meio sobre Judá; trinta e três anos, em Jerusalém, sobre todo o Israel e sobre Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'O rei foi com toda a gente que tinha consigo a Jerusalém, contra os Jebuseus, que moravam, naquele território. Estes disseram a Davide: Não entrarás cá, sem que lances fora os cegos e os coxos, os quais estão dizendo: Davide não entrará aqui. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Porém Davide tomou a fortaleza de Sião, que é a cidade de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Naquele dia Davide disse: Todo o que ferir os Jêbuseus e atingir o alto da fortaleza e expulsar os cegos e os coxos, inimigos de Davide, (será chefe e príncipe). Por isso se diz em provérbio: Nem cego nem coxo entrarão no templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'Davide habitou na fortaleza, e chamou-a cidade de Davide; levantou edifícios ao redor, desde Melo, e no interior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'Davide ia-se fortificando e crescendo mais e mais, e o Senhor Deus dos exércitos era com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Hiram, rei de Tiro, enviou mensageiros a Davide, com madeira de cedro, assim como carpinteiros e canteiros que edificaram uma casa a Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Davide reconheceu que o Senhor o tinha confirmado rei sobre Israel, e que exaltava o seu reino por amor do seu povo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Davide tomou outras mulheres, de segunda e primeira ordem, de Jerusalém, depois que veio de Hebron, e teve delas filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Estes são os nomes dos que lhe nasceram em Jerusalém: Samua, Sobab, Natan, Salomão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Jebabar, Elisua, Nefeg,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Jafa, Elisama, Elioda e Elifalet.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Os Filisteus, ouvindo dizer que Davide tinha sido ungido rei sobre Israel, subiram todos em busca de Davide. Sabendo isto Davide, retirou-se a um lugar forte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'Os Filisteus fizeram uma incursão pelo vale dos Refains.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 19, 'Davide consultou o Senhor, dizendo: Marcharei contra os Filisteus? Entregarmos-ás tu nas minhas mãos? O Senhor respondeu a Davide: Vai, que eu entregarei os Filisteus nas tuas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 20, 'Foi, pois, Davide a Baal Farasim, onde os derrotou, e disse: O Senhor irrompeu sobre os meus inimigos à minha vista, como águas que irrompem sobre os diques, despedaçando-os. Por isso aquele lugar foi chamado Baal Farasim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 21, 'Os Filisteus deixaram lá os seus ídolos, os quais Davide e a sua gente levaram (para queimar).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 22, 'Os Filisteus voltaram novamente e espalharam-se pelo vale dos Refains.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 23, 'Davide consultou o Senhor: Irei eu contra os Filisteus, e entregá-los-ás nas minhas mãos? O Senhor respondeu-lhe: Não vás direto a eles, mas dá volta por detrás deles, e irás contra eles, do lado dos balsameiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 24, 'Quando ouvires um rumor como de passos, entre as copas dos balsameiros, então travarás a batalha, porque o Senhor marchará então diante de ti, para ferir o acampamento dos Filisteus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 25, 'Fez, pois, Davide como o Senhor lhe tinha mandado, e derrotou os Filisteus desde Gabaa até chegar a Gezer.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Davide juntou de novo todos os homens escolhidos de Israel, em número de trinta mil,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'levantou-se e partiu com toda a gente da tribo de Judá, que, estava com ele, para transportar a arca de Deus, sobre a qual é invocado o nome do Senhor dos exércitos, que tem o seu assento sobre ela, entre os querubins.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Puseram a arca de Deus sobre um carro novo, e levaram-na da casa de Abinadab, que estava sobre a colina. Oza e Ahlo, filhos de Abinadab, conduziam o carro novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Tendo-a tirado da casa de Abinadab, que estava sobre a colina, Ahio ia adiante da arca guardando a arca de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'Davide, porém, e todo o Israel dançavam diante do Senhor ao som de toda a casta de instrumentos de madeira, e cítaras, e liras, e tímpanos, e sistros, e címbalos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'Quando chegaram à eira de Nacon, Oza estendeu a mão para a arca de Deus e susteve-a, porque os bois escoicinhavam, e tinham-na feito pender.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'O Senhor indignou-se muito contra Oza, e feriu-o pela sua temeridade: Oza caiu morto ali mesmo junto da arca de Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Davide contristou-se, porque o Senhor tinha ferido Oza. Aquele lugar ficou-se chamando até ao dia de hoje: Castigo de Oza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'Davide temeu o Senhor, naquele dia, dizendo: Como entrará a arca do Senhor em minha casa?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'E não quis que levassem a arca do Senhor para sua casa, na cidade de Davide, mas fê-la ir para casa de Obededom, de Get.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'A arca do Senhor esteve três meses em casa de Obededom, de Get, e o Senhor abençoou Obededom e toda a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Foi anunciado ao rei Davide que o Senhor tinha abençoado Obededom e tudo o que lhe pertencia, por causa da arca de Deus. Foi então Davide, e levou a arca de Deus de casa de Obededom para a cidade de Davide, com um jubiloso cortejo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Quando os que levavam a arca do Senhor tinham dado seis passos, foi oferecido um sacrifício de um boi e de um carneiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Davide dançava diante do Senhor com todas as suas forças, cingido dum éfode de linho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Davide e toda a casa de Israel conduziram a arca do testamento do Senhor com júbilo e ao som de trombetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Quando entrou a arca do Senhor na cidade de Davide, Micol, filha de Saul, olhando da janela, viu o rei Davide dançando e saltando diante do Senhor, e desprezou-o em seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'Introduziram a arca do Senhor e colocaram-na no seu lugar, no meio do tabernáculo, que Davide lhe tinha preparado; depois disto Davide ofereceu holocaustos e vítimas pacíficas diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Quando acabou de oferecer os holocaustos e as vítimas pacíficas, abençoou o povo em nome do Senhor dos exércitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'A seguir distribuiu a todo o povo de Israel, tanto a homens como a mulheres, a cada um um a torta de pão, um pedaço de carne de vaca assada, e uma pasta de uvas. E retirou-se todo o povo, cada um para sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'Retirou-se também Davide a sua casa, para a abençoar. Micol, filha de Saul, tendo saído ao encontro de Davide, disse: Que bela figura fez hoje o rei de Israel, despindo-se (das suas insígnias), diante das escravas de seus vassalos, e desnudando-se como faria um chocarreiro'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'Davide disse a Micol: Diante do Senhor, que me escolheu, preferindo-me a teu pai e a toda a sua família, e que me mandou que fosse eu o condutor do povo do Senhor em Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'não só dançarei, mas também me farei mais vil do que me tenho feito, serei mais humilde aos teus olhos, e com isto aparecerei com mais glória diante das escravas, de que falaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'E Micol, filha de Saul, não teve mais filhos até ao dia da sua morte.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Ora aconteceu que, estando o rei estabelecido em sua casa, e tendo-lhe o Senhor dado paz por todas as partes com todos os seus inimigos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'disse ele ao profeta Natan: Tu não vês que habito numa casa de cedro, enquanto a arca de Deus está posta debaixo dumas peles?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Natan respondeu ao rei: Vai e faze tudo o que tens no coração, porque o Senhor é contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'Naquela mesma noite, o Senhor falou a Natan, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'Vai e dize ao meu servo Davide: Eis o que o diz o Senhor: Porventura serás tu que me edificarás uma casa para eu habitar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Vê que eu, desde que tirei da terra do Egipto os filhos de Israel até ao dia de hoje, não habitei em nenhum a casa, mas tenho caminhado debaixo dum pavilhão e duma tenda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Em todos os lugares, por onde passei com todos os filhos de Israel, falei eu porventura a algum dos chefes de Israel, a esses que mandei pastorear o meu povo de Israel, dizendo: Por que não me edificais uma casa de cedro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Dirás, pois, ao meu servo Davide: Eis o que diz O Senhor dos exércitos: Eu tirei-te das pastagens, quando ias seguindo os gados, para que fosses o condutor do meu povo de Israel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'por toda a parte por onde andaste, estive contigo, exterminei diante de ti todos os teus inimigos, e fiz o teu nome tão ilustre como o nome dos grandes que há na terra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'fixei um lugar ao meu povo de Israel e coloquei-o nele, onde habitará, sem ser mais perturbado (se permanecer fiel aos meus preceitos); os filhos da iniquidade não tornarão a afligi-lo como dantes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'desde o dia em que eu constituí juízes sobre o meu povo de Israel; dei-te paz, (livrando-te) de todos os teus inimigos. (Pois agora) o Senhor te anuncia (desde já) que te fará uma casa. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'Quando se completarem os teus dias, e dormires com teus pais, suscitarei depois de ti a tua posteridade, que nascerá de ti, e firmarei o seu reino. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Ele edificará uma casa em meu nome, e eu estabelecerei para sempre o trono de seu reino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Eu serei para ele um pai, e ele será para mim um filho. Se ele cometer alguma coisa iníqua, eu o castigarei com vara de homens, e com açoutes de filhos de homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'Porém , não retirarei dele a minha misericórdia, como a retirei de Saul, a quem expulsei de diante da minha face.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'A tua casa será estável, o teu reino se perpetuará diante do teu rosto, e o teu trono será firme para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Seguindo todas estas palavras e toda esta visão, falou Natan a Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Entrou o rei Davide, sentou-se diante, do Senhor e disse: Quem sou eu, ó Senhor Deus, e que casa é a minha, para tu me teres elevado a este ponto?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'Mas isto mesmo te pareceu pouco, ó Senhor Deus, pois falaste também (prometendo a permanência) da casa de teu servo para tempos distantes; porque esta é a lei do homem, ó Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Que poderá, pois, acrescentar ainda Davide, falando contigo? Tu, ó Senhor Deus, conheces o teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Por atenção à tua palavra e segundo o teu coração, fizeste todas estas maravilhas, até ao ponto de as dares a saber ao teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Por isso, ó Senhor Deus, mostraste a tua grandeza! Ninguém há semelhante a ti, nem há Deus, fora de ti, segundo tudo o que temos ouvido com os nossos ouvidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Que nação há, na terra, igual ao teu povo de Israel, a quem Deus foi resgatar, para o fazer seu povo, dar-lhe um nome célebre, e operar em seu favor prodígios (tão) terríveis, a fim de o tirar da escravidão do Egipto, (e a fim de punir aquela terra), o seu povo, e o seu (falso) deus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Tu estabeleceste o povo de Israel, para ser eternamente o teu povo, e tu te fizeste o seu Deus, ó Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Agora, pois, ó Senhor Deus, faze que tenha efeito para sempre a palavra que pronunciaste acerca do teu servo e da sua casa, e faze como disseste,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'para que o teu nome seja eternamente engrandecido e se diga: O Senhor dos exércitos é o Deus de Israel. A casa de teu servo Davide permanecerá estável diante do Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 27, 'porque tu, ó Senhor dos exércitos, Deus de Israel, te revelaste ao ouvido do teu servo, dizendo: Eu te edificarei uma casa; por isso o teu servo se animou a dirigir-te esta prece.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 28, 'Agora, ó Senhor Deus, tu és Deus e as tuas palavras são verdadeiras. Ora tu mesmo prometeste ao teu servo estes bens;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 29, 'começa, pois, e abençoa a casa de teu servo, para que ela subsista para sempre diante de ti, porque tu, ó Senhor Deus, é que falaste, e com a tua bênção será para sempre bem-dita a casa do teu servo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Depois disto Davide derrotou os Filisteus e humilhou-os, tirando-lhes o mando da sua capital.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'Derrotou também os Moabitas, e (os prisioneiros) mediu-os a cordel, fazendo-os deitar por terra: duas medidas de cordel para a morte e uma medida avantajada para a vida. E ficou Moab sujeito a Davide, pagando-Ihe tributo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'Davide derrotou também Adadezer, filho de Roob, rei de Soba, quando marchou para estender os seus domínios até ao rio Eufrates.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'Tendo-lhe Davide tomado mil e setecentos cavaleiros e vinte mil peões, cortou os jarretes a todos os cavalos dos carros; deles reservou sòmente (os precisos) para cem carros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Vieram também os Sírios de Damasco, para darem socorro a Adadezer, rei de Soba, e Davide matou vinte e dois mil Sírios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Davide pôs guarnição na Síria de Damasco, e a Síria foi submetida a Davide, ficando-lhe tributária. O Senhor guardou Davide em todas as expedições que fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'Davide tomou as armas de ouro, que tinham os servos de Adadezer, e levou-as para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'De Bete e de Berot, cidades de Adadezer, Davide tomou uma grande quantidade de cobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Quando Tou, rei de Emat, ouviu dizer que Davide tinha quebrado todas as forças a Adadezer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'enviou Jorão, seu filho, ao rei Davide para o saudar, dando-lhe os parabéns, e para lhe dar graças por ter vencido e destroçado Adadezer, porque Tou era inimigo de Adadezer. (Jorão) levava na sua mão vasos de ouro, de prata e de cobre,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'os quais o rei Davide consagrou também ao Senhor, com a prata e ouro, que lhe tinha consagrado do despojo de todas as nações que sujeitara,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'da Síria e de Moab, dos filhos de Amon, dos Filisteus e de Amalec, com os despojos de Adadezer, filho de Roob, rei de Soba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Adquiriu Davide grande fama, quando, na volta da conquista da Síria, matou dezoito mil homens no vale das Salinas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'Pôs na Idumeia guarnições, e toda a Idumeia ficou sujeita a Davide. O Senhor guardou Davide em todas as expedições que fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Reinou Davide sobre todo o Israel, e julgava também e administrava justiça a todo o seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'Josafat, filho de Ailude, era seu cronista;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Sadoc, Joab, filho de Sarvia, era o general dos seus exércitos; filho de Aquitob, e Aquimeleque, filho de Abiatar, eram pontífices; Saraias era secretário;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Banaias, filho de Jojada, mandava nos Cereteus e Feleteus; e os filhos de Davide eram seus conselheiros íntimos.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Davide disse: Sabeis se ficou alguém da casa de Saul, para que eu lhe faça bem por amor de Jónatas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Ora havia um criado da casa de Saul, chamado Siba, que o rei chamou à sua presença, e ao qual disse: Tu és Siba? E ele respondeu: Sou eu, teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'O rei disse: Porventura ficou alguém da casa de Saul, para quem eu possa usar de misericórdia (grande como) de Deus? Siba respondeu ao rei: Ficou ainda um filho de Jónatas, aleijado dos pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'Onde está ele? disse Davide. Siba disse ao rei: Está em Lodabar, em casa de Maquir, filho de Amiel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'Mandou, pois, o rei Davide buscá-lo, e o fez trazer de Lodabar, de casa de Maquir, filho de Amiel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Mifiboset, filho de Jónatas, filho de Saul, tendo chegado à presença de Davide, prostrou-se com o rosto por terra e fez-lhe uma profunda reverência. Davide disse: Mifiboset? Ele respondeu: Aqui tens o teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'Davide disse-lhe: Não temas, porque eu estou resolvido a fazer-te todo o bem em atenção a Jónatas, teu pai, restituir-te-ei todos os bens de Saul, teu avô, e tu comerás sempre à minha mesa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Mifiboset, inclinando-se profundamente, disse: Quem sou eu, teu servo, para tu teres olhado para um cão morto como eu sou?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Mandou o rei chamar Siba, criado de Saul, e disse-lhe: Eu dei ao filho do teu amo tudo o que pertencia a Saul e a toda a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Tu, pois, com teus filhos e servos, cultivar-lhe-ás as suas terras, e cuidarás de subministrar ao filho do teu amo alimentos para que se sustente; Mifiboset, porém, filho do teu amo, comerá sempre à minha mesa. Ora Siba tinha quinze filhos e vinte servos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Siba disse ao rei: Conforme tu mandaste, ó rei meu senhor, ao teu servo, assim o fará teu servo. Quanto a Mifiboset (repetiu Davide) comerá à minha mesa, como um dos filhos do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Mifiboset tinha um filho ainda criança, chamado Mica, e toda a parentela da casa de Siba estava ao seu serviço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'Vivia Mifiboset em Jerusalém, porque todos os dias comia à mesa do rei. Era coxo de ambos os pés.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Aconteceu, depois disto, morrer o rei dos Amonitas, sucedendo-lhe, no reino, Hanon, seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'Davide disse: Eu mostrarei benevolência a Hanon, filho de Naas, como seu pai me mostrou a mim. Enviou, pois, Davide em baixadores, para o consolar na morte de seu pai. Todavia, quando os enviados de Davide chegaram ás terras dos Amonitas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'os príncipes dos Amonitas disseram a Hanon, seu senhor: Tu cuidas que é em honra de teu pai, que Davide te enviou estes homens para te consolar? Não te enviou, antes, os seus servos para investigarem e reconhecerem a cidade, e para a destruirem?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Prendeu, então, Hanon os servos de Davide, mandou-lhes rapar metade da barba e cortar-lhes metade dos seus vestidos, até cerca da cintura, e despediu-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Davide, quando isto lhe foi referido, mandou enviados ao seu encontro porque aqueles homens estavam sobremaneira, envergonhados com a afronta que lhes dissessem: Deixai-vos estar em Jericó, até que vos cresça a barba, e depois voltareis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Considerando os Amonitas que tinham injuriado Davide, mandaram aos Sírios de Rood e aos Sírios de Soba, e tomaram deles a seu soldo vinte mil homens de pé, mais de mil homens dos do rei de Maaca e doze mil dos de Tob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Advertido disto Davide, mandou Joab (contra eles) com todas as suas tropas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'Os Amonitas saíram à campanha, dispondo o seu exército em batalha em frente à entrada da porta (da cidade); os Sírios de Soba, os de Roob, os de Istob e os de Maaca, estavam a parte no campo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Joab, vendo que estava preparada batalha contra ele, assim pela frente como pela retaguarda, escolheu entre os melhores de Israel, e formou em linha de batalha contra os Sírios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'O resto do exército entregou-o a seu Irmão Abisai, que dirigiu o combate contra os Amonitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Joab disse-lhe: Se os Sírios prevalecerem contra mim, virás em meu socorro: se os Amonitas prevalecerem contra ti, eu te socorrerei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'Mostra-te como homem de coragem, e pelejemos pelo nosso povo e pela cidade do nosso Deus. O Senhor fará como bem lhe parecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'Joab, com a gente que estava com ele, travou o combate contra os Sírios, os quais fugiram logo diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Os Amonitas, vendo que os Sírios tinham fugido, fugiram também eles, diante de Abisai, e entraram na cidade. Joab voltou dos filhos de Amon, e foi para Jerusalém'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'Os Sírios, vendo que tinham sido derrotados por Israel, tornaram a refazer-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Adadezer mandou vir os Sírios, que estavam da outra banda do rio, e conduziu as suas tropas; Sobac, general do exército de Adadezer, comandava-as.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Davide, informado disto, juntou todo o Israel, passou o Jordão e foi até Helam. Os Sírios ordenaram o seu exército contra Davide e combateram contra ele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'mas puseram-se em fuga à vista de Israel; Davide destroçou setecentos carros dos Sírios e quarenta mil homens de cavalo, e feriu Sobac, general do exército, o qual morreu logo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'Todos os reis, que tinham ido em auxílio de Adadezer, vendo que estavam vencidos pelos Israelitas, tiveram medo e fugiram à vista dos Israelitas, em número de cinqüenta e oito mil homens, e fizeram pazes com os Israelitas ficando-lhes sujeitos. De então por diante os Sírios não ousaram mais dar socorro aos Amonitas.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Ora sucedeu que, decorrido um ano, no tempo em que os reis costumam ir para a guerra, Davide enviou Joab com os seus oficiais e todo o (exército de) Israel, que destruíram os Amonitas, e sitiaram Raba. Davide, porém, ficou em Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'Enquanto assim passavam as coisas, levantando-se, uma tarde, Davide de dormir a sesta, pôs-se a passear no terraço do palácio real e viu uma mulher que se banhava, defronte do seu terraço, mulher muito formosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'Mandou o rei saber quem era aquela mulher. Disseram-lhe que era Betsabé, filha de Elião, mulher de Urias Heteu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Então Davide mandou mensageiros, que Iha trouxessem. Ela veio e Davide dormiu com ela. Ela purificou-se logo da sua imundicie,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'e voltou para sua casa tendo concebido. E mandou dizer a Davide: Concebi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'Davide mandou dizer a Joab: Envia-me Urias Heteu. Joab enviou Urias a Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Urias apresentou-se a Davide, e Davide perguntou-lhe se passava bem Joab e o povo, e como ia a guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Davide disse a Urias: Vai para tua casa, e lava os teus pés. Urias saiu do palácio do rei, e após ele foi-lhe mandado alimento da mesa real.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Urias, porém, dormiu junto da porta do palácio real com outros oficiais do seu senhor, e não foi a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Avisaram disto a Davide, dizendo: Urias não foi a sua casa. Davide disse a Urias: Não vieste tu duma jornada? Por que não foste a tua casa?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Urias respondeu a Davide: Enquanto a arca de Deus, e Israel e Judá, habitam debaixo de tendas, e o meu senhor Joab e os servos do meu senhor dormem sobre a terra dura, eu deveria ir para minha casa comer, beber e dormir com minha mulher? Pela tua vida e pela saúde da tua alma (juro que) não farei tal coisa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Disse Davide a Urias: Fica ainda hoje aqui, e amanhã te enviarei. Urias ficou em Jerusalém aquele dia e o seguinte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Davide convidou-o a comer e a beber em sua presença, e embriagou-o, mas Urias, saindo já de noite, dormiu na sua cama com os oficiais do seu senhor, e não foi a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Chegada a manhã, Davide escreveu um a carta a Joab, enviando-lha por mão de Urias. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Dizia na carta: Ponde Urias na frente, onde for mais rijo o combate, e desamparai-o, para que seja ferido e morra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Joab, tendo sitiado a cidade, pôs Urias defronte do lugar onde sabia que estavam os homens mais valentes (dos inimigos).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'Tendo os homens da cidade feito uma sortida, combatiam contra Joab, e morreram alguns do exército de Davide, morrendo também Urias Heteu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Joab mandou dizer a Davide tudo o que se tinha passado no combate,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'e deu ao mensageiro esta ordem; Depois que tiveres acabado de contar ao rei tudo o que se passou no combate,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'se vires que ele se indigna e diz: Por que fostes vós combater tão perto dos muros? Não sabíeis que são muitos os dardos que se arremessam do alto do muro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Quem matou Abimeleque, filho de Jerobaal? Não foi uma mulher que, do alto da muralha, atirou para cima dele um pedaço de mó de moinho, e o matou em Tebes? Porque vos aproximastes tanto dos muros? tu lhe dirás: Também morreu o teu servo Urias Heteu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Partiu o mensageiro que, chegando junto de Davide, lhe referiu tudo o que Joab lhe tinha mandado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'O mensageiro disse a Davide: Os inimigos prevaleceram contra nós e fizeram uma saída contra o nosso acampamento, mas nós, dando sobre eles, os perseguimos até à porta da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Os frecheiros dirigiram os tiros contra os teus servos, do alto do muro, e morreram alguns dos servos do rei, morrendo também Urias Heteu, teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'Davide disse ao mensageiro: Dirás isto a Joab: Não percas por isso o ânimo, porque os sucessos da guerra são vários; ora perece um, ora perece outro, aos golpes da espada; anima os teus soldados e esforça-os contra a cidade, para a destruires.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 26, 'A mulher de Urias soube que Urias, seu marido, tinha morrido, e chorou por ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'Passado o tempo do luto, Davide mandou-a vir para o seu palácio, tomou-a por sua mulher, e ela deu-lhe á luz um filho. Mas isto que Davide tinha feito foi desagradável aos olhos do Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'O Senhor, pois, enviou Natan a Davide, e Natan, tendo chegado à sua presença, disse-lhe: Havia numa cidade (do teu reino) dois homens, um rico e outro pobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'O rico tinha ovelhas e bois em grande número.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'O pobre, porém, não tinha coisa alguma, senão uma ovelhinha, que comprara e criara, e que tinha crescido em sua casa juntamente com seus filhos, comendo do seu pão, bebendo do seu mesmo copo e dormindo no seu regaço; e ele queria-lhe com o se fosse uma sua filha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Tendo chegado um hóspede a casa do rico, não querendo este tocar nas suas ovelhas nem nos seus bois, para dar um banquete ao hóspede, que lhe tinha chegado, tomou a ovelha do pobre e preparou-a para dar de comer ao homem que tinha vindo a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Davide, sumamente indignado contra tal homem, disse a Natan: Viva o Senhor, um homem que tal fez é digno de morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Pagará o quádruplo da ovelha, por ter feito dela o que fez, e não ter poupado (o pobre).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'Então Natan disse a Davide: Tu és esse homem. Eis o que diz o Senhor Deus de Israel: Eu te ungi rei sobre Israel, e te livrei da mão de Saul,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'dei-te a casa do teu senhor, pus ao teu dispor as suas mulheres, a casa de Israel e de Judá; se isto é pouco, juntar-te-ei ainda coisas muito maiores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'Por que desprezaste, pois a palavra do Senhor, até cometeres o mal diante de meus olhos? Fizeste perecer à espada Urias Heteu, e tomaste para tua mulher a que era sua mulher, e mataste-lo com a espada dos filhos de Amon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Por esta razão não se apartará jamais a espada da tua casa, porque me desprezaste, tomando a mulher de Urias Heteu, para ser tua mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'Eis pois o que diz o Senhor: Eu suscitarei da tua mesma casa o mal sobre ti, tomarei as tuas mulheres, à tua vista, e dá-las-ei a um teu próximo, que dormirá com as tuas mulheres à luz deste sol.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'Tu procedeste ocultamente, mas eu farei estas coisas à vista de todo o Israel, à luz do sol.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'Davide disse a Natan; Pequei contra o Senhor. Natan respondeu a Davide: Também o Senhor perdoou o teu pecado (por ver o teu arrependimento): não morrerás. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Todavia, visto que tu, pelo que fizeste, deste lugar a que os inimigos do Senhor blasfemem, morrerá irremissivelmente o filho, que te nasceu (do adultério).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'E Natan voltou para sua casa. O Senhor feriu (de enfermidade) o menino, que a mulher de Urias tinha dado à luz a Davide, e ele adoeceu gravemente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'Davide fez oração ao Senhor pelo menino, jejuou rigorosamente e, retirando-se à parte, prostrou-se sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'Os anciães da sua casa vieram para o abrigar a levantar-se do chão, mas ele não o quis fazer, nem comeu com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Ao sétimo dia, morreu o menino, e os servos de Davide não ousaram dizer-lhe que o menino tinha morrido, porque diziam: Quando o menino ainda vivia, nós falávamos-lhe, e ele não queria ouvir-nos; quanto mais se afligirá ele, se lhe dissermos que o menino morreu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'Davide, porém, vendo os seus servos a falar em segredo, compreendeu que o menino tinha morrido e disse-lhes: Porventura morreu o menino? Eles responderam-lhe: Morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'Então Davide levantou-se do chão, lavou-se e ungiu-se, e, tendo mudado de roupa, entrou na casa do Senhor e o adorou (completamente resignado). (Depois) foi para sua casa e pediu que lhe pusessem de comer, e comeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'Os seus servos disseram-lhe: Como fizeste assim? Tu jejuaste e choraste pelo menino, quando ele ainda vivia, e, agora que morreu, levantaste-te e comeste?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, '(Davide) respondeu: Eu jejuei e chorei pelo menino enquanto vivo, porque dizia: Quem sabe se talvez o Senhor terá pena de mim e fará viver o menino?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'Mas agora que ele morreu, por que hei-de jejuar? Porventura posso eu fazê-lo ainda viver? Eu Irei para junto dele, mas ele não voltará mais para junto de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'Depois Davide consolou sua mulher Betsabé, foi dormir com ela, e ela gerou um filho, a que pôs o nome de Salomão. O Senhor o amou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 25, 'e enviou o profeta Natan, o qual deu ao menino o nome de Amável ao Senhor, porque o Senhor o amava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 26, 'Entretanto Joab continuava a combater contra Raba dos Amonitas, e tomou a cidade real.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 27, 'e Joab enviou mensageiros a Davide, dizendo: Tenho combatido contra Raba, e a cidade das Águas está tomada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 28, 'Agora, junta o resto do povo, vem ao sítio da cidade e toma-a, para não suceder que, tendo eu destruído a cidade, se atribua ao meu nome a vitória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 29, 'Juntou Davide todo o povo, marchou contra Raba e, depois de ter combatido, a tomou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 30, 'Tirou da cabeça do rei dos Amonitas o seu diadema, que pesava um talento de ouro, enriquecido de pedras preciosíssimas, o qual foi posto na cabeça de Davide. E levou da cidade muitíssimos despojos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 31, 'Quanto aos seus moradores deportou-os, empregando-os em serrar, em a fiar ferros, em serviços com machados e em trabalhos em fornos de cozer tijolo. Assim fez a todas as cidades dos Amonitas. Em seguida, Davide voltou com todo o exército para Jerusalém');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Aconteceu, depois disto, que Amnon, filho de Davide, se enamorou de Tamar, Irmã de Absalão filho de Davide, a qual era duma rara beleza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Apaixonou-se de tal modo por ela que, por causa do seu amor, caiu doente, pois sendo ela virgem, parecia-lhe difícil fazer com ela coisa alguma contra a honestidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Tinha porém Amnon um (mau) amigo, homem muito sagaz, chamado Jonadab, filho de Semaa, irmão de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'Este disse a Amnon: Como vais tu de dia para dia emagrecendo, ó filho do rei? Por que te não descobres tu comigo? Amnon disse-lhe: Eu amo Tamar, irmã do meu irmão (consanguineo) Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Respondeu-lhe Jonadab; Deita-te na tua cama e finge que estás doente; quando teu pai te vier visitar, dize-lhe: Peço-te que mandes vir aqui minha irmã Tamar, para que me dê de comer, e me prepare algum prato, que eu possa comer da sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Deitou-se, pois, Amnon na cama e começou a fingir-se doente. Tendo ido o rei visitá-lo, disse Amnon ao rei: Peço-te que mandes vir minha irmã Tamar, para que faça á minha vista dois pastéizinhos, que eu coma da sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Mandou Davide a casa de Tamar dizer-lhe; Vem a casa de teu irmão Amnon, e faze-lhe alguma coisa de comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Tamar foi a casa de seu irmão Amnon, que estava na cama, e, tomando um pouco de farinha, misturou-a e, adelgaçando-a, cozeu à sua vista uns pastèizinhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'Tomando o que tinha cozido, lançou-o num prato e pôs-lhe diante, mas Amnon não quis comer e disse: Façam sair todos para fora. Tendo feito sair todos para fora,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Amnon disse a Tamar: Chega-me cá à alcova essa comida, para que eu a coma da tua mão. Tomou pois Tamar o que tinha cozido, e levou-o a seu irmão Amnon à alcova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Logo que ela lhe pôs diante o prato, pegou nela, e disse: Vem, minha irmã, deita-te comigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Porém ela respondeu-lhe: Não, meu Irmão, não me faças esta violência, pois que isto não é lícito em Israel; não faças tal loucura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Eu não poderei sofrer o meu opróbrio, e tu passarás em Israel por um insensato; mais vale que fales ao rei (para me tomar como esposa), e ele não me negará a ti. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Amnon não quis ceder a seus rogos, e, como era mais forte do que ela, violentou-a e desflorou-a.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'Amnon ganhou-lhe uma extrema aversão, de sorte que o ódio que concebeu contra ela excedia muito o amor que antes lhe tivera. Amnon disse-lhe: Levan­ta-te, e vai-te.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'Ela respondeu-lhe: Este ultraje que tu agora me fazes, lançando-me fora, é maior do que aquele que primeiro me fizeste. Amnon não a quis ouvir,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'antes, chamando um criado que o servia, disse-lhe: Deita-a fora daqui, e fecha a porta nas suas costas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Tamar estava vestida duma túnica talar (de várias cores), porque este era o traje que costumavam trazer as donzelas, filhas do rei. O criado de Amnon deitou-a fora e fechou a porta após ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'Tamar lançou cinza sobre a sua cabeça, rasgou a túnica talar e postas as mãos na cabeça, foi-se dali dando gritos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'Absalão, seu irmão, disse-lhe: Porventura teu irmão Amnon abusou de ti? Agora, porém, ó minha irmã, cala-te; ele é teu irmão; não se angustie o teu coração por isso. Ficou Tamar, desolada, em casa de seu irmão Absalão. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'O rei Davide, tendo ouvido estas coisas, afligiu-se muito, mas não quis contristar o ânimo de Amnon, seu filho, porque o amava por ser o seu primogênito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Absalão não falou a Amnon nem mal nem bem, mas odiava-o, por ter violado sua irmã Tamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'Dois anos depois aconteceu tosquiarem-se as ovelhas de Absalão em Baalhasor, que é junto de Efraim, e Absalão convidou todos os filhos do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 24, 'E foi ter com o rei e disse-lhe: Eis que se tosquiam as ovelhas do teu servo; rogo, pois, que venha o rei com os seus criados a casa do seu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 25, 'O rei disse a Absalão: Não, meu filho, não nos peças que vamos todos, e te sejamos pesados. Porém, Absalão instou, mas Davide não quis ir e deu-lhe a sua bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 26, 'Absalão disse: Se tu não queres vir, suplico-te que ao menos venha conosco meu irmão Amnon. O rei disse-lhe: Não é necessário que ele vá contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 27, 'Todavia Absalão instou mais, e Davide deixou ir com ele Amnon e todos os filhos do rei. Absalão tinha preparado um banquete, como um banquete real.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 28, 'Ora Absalão tinha dado esta ordem aos seus criados: Estai atentos; quando Amnon estiver turvado pelo vinho, e eu vos der sinal, dai nele e matai-o; não tenhais medo, porque sou eu quem vo-lo manda; tende coragem, e sede homens fortes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 29, 'Os criados de Absalão fizeram a Amnon como Absalão lhes tinha ordenado. Todos os filhos do rei, levantando-se da mesa, montaram cada um na sua mula e fugiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 30, 'Indo eles ainda no caminho, chegou aos ouvidos de Davide o rumor que Absalao matara todos os filhos do rei, sem que ficasse deles nem um só.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 31, 'Levantou-se então o rei, rasgou os seus vestidos e lançou-se por terra; todos os criados, que lhe assistiam, rasgaram (também) os seus vestidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 32, 'Jonadab, filho de Semaa, irmão de Davide, tomando a palavra, disse: Não imagine o rei, meu senhor, que foram mortos todos os seus filhos; só morreu Amnon, porque assim o tinha resolvido fazer Absalão, desde o dia em que Amnon fez violência a sua irmã Tamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 33, 'Não acredite o rei, meu senhor, que todos os filhos do rei foram mortos, pois só morreu Amnon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 34, 'Entretanto Absalão fugiu. Levantando os olhos, o criado que estava de sentinela, viu grande multidão de gente, que vinha por um caminho escuso ao lado do monte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 35, 'Jonadab disse ao rei; Eis lá vêm os filhos do rei; sucedeu como disse o teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 36, 'Acabando ele de falar, apareceram os filhos do rei, que entrando, levantaram a voz e choraram. O rei e todos os seus servos também choraram com pranto muito amargo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 37, 'Absalão fugiu para casa de Tolomai, filho de Amiud, rei de Bessur. Davide chorava o seu filho todos os dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 38, 'Absalão, tendo fugido, acolheu-se a Gessur, onde esteve três anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 39, 'E o rei Davide deixou de perseguir Absalão, porque já se tinha consolado da morte de Amnon.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Joab, filho de Sarvia, advertindo que o coração do rei estava inclinado para Absalão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'mandou vir de Tecua uma mulher hábil, e disse-lhe: Finge que estás de luto, toma um vestido de dó, e não te unjas com óleo, para pareceres uma mulher que chora um morto há muito tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Apresentar-te-ás ao rei, e lhe dirás tais e tais palavras. E Joab pôs-lhe na boca tudo o que havia de dizer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'Tendo-se apresentado ao rei esta mulher de Tecua, lançou-se por terra diante dele, fez-lhe uma profunda reverência e disse: Salva-me, ó rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'O rei disse-lhe: Que tens? Ela respondeu: Ai! eu sou uma mulher viúva: morreu o meu marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'A tua serva tinha dois filhos, os quais tiveram uma briga no campo entre si, e não houve ninguém que os pudesse apartar; um feriu o outro, e matou-o.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'Agora toda a parentela, levantando-se contra a tua serva, diz: Dá-nos esse que matou o seu irmão, para o matarmos em castigo do sangue do seu irmão, a quem matou, e tirarmos do mundo o herdeiro. Assim pretendem apagar a única brasa que me ficou, de modo que não se conserve o nome do meu marido, nem resto algum sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'O rei disse à mulher: Vai para tua casa, que darei ordem em teu favor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'A mulher de Tecua, porém, disse ao rei: Sobre mim, ó rei meu senhor, recaia a culpa, e sobre a casa de meu pai; mas o rei e o seu trono sejam inocentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'O rei disse: Se alguém te contradisser, traze-o à minha presença, e está certa de que ele te não inquietará mais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'Ela disse: Recorde-se o rei do Senhor seu Deus, para que se não multipliquem os parentes do morto, para tomarem vingança e de modo algum matem o meu filho. Ele respondeu: Viva o Senhor! (juro) que não há-de cair no chão um único cabelo do teu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Disse então a mulher: Permite que a tua serva diga uma palavra ao rei, meu senhor. Ele disse: Fala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'A mulher disse: Por que pensaste tu (fazer) uma coisa semelhante contra o povo de Deus? Proferindo tal sentença, o rei se dá por culpado, pelo facto, de não chamar aquele que desterrou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'Nós todos vamos morrendo, e corremos pela terra como águas, que não voltam mais. Deus não quer que alguma alma pereça, antes está sempre disposto a revogar a sentença, para que se não perca de todo o que está abatido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Se, agora, vim dizer esta palavra ao rei, foi porque o povo me aterrou. A tua serva disse: Falarei ao rei, a ver se dalgum modo consigo dele a graça que lhe peço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'Sim, o rei ouvir-me-á e livrará a sua serva da mão de todos os que me querem exterminar a mim e ao meu filho da herança (do povo) de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'A tua serva disse: Que a palavra do rei, meu senhor me tranquilize, porque o rei meu senhor é como um anjo de Deus, para discernir o bem do mal. E, agora, que o Senhor teu Deus seja contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'Respondendo o rei, disse à mulher: Não me encubras o que te vou perguntar. A mulher disse: Fala, ó rei, meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'O rei disse: Não é verdade que a mão de Joab anda contigo em tudo isto? Respondeu a mulher: Por tua vida, ó rei meu senhor, em nada se aparta (da verdade) tudo o que disse o rei meu senhor, nem para a direita nem para a esquerda, porque com efeito o teu servo Joab é quem me deu esta ordem, e quem pôs todas estas palavras na boca da tua serva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'Foi o teu servo Joab que me mandou servir desta parábola. Porém tu, ó rei meu senhor, és sábio como o é um anjo de Deus, para entenderes tudo o que se passa sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'O rei disse a Joab: Vou fazer o que pedes; anda, faze voltar o jovem Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'Joab, prostrando-se por terra sobre o seu rosto, fez uma profunda reverência, abençoou o rei, e disse: Hoje, ó rei meu senhor, o teu servo conheceu que achou graça diante dos teus olhos, porque deferiste a súplica do teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, 'Partiu, logo, Joab, foi a Gessur e conduziu Absalão para Jerusalém'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 24, 'Mas o rei disse: Volte para sua casa, sem aparecer diante de mim. Absalão foi, e não viu a face do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 25, 'Em todo o Israel não havia homem tão belo, nem tão gentil, como Absalão; da planta dos pés até à cabeça não havia nele defeito algum.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 26, 'Quando cortava o cabelo (o que fazia um a vez cada ano, porque o incomodava a cabeleira), o cabelo da sua cabeça pesava duzentos ciclos, pelo peso real.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 27, 'Absalão teve três filhos e uma filha chamada Tamar, de extrema for­mosura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 28, 'Absalão esteve em Jerusalém dois anos, e não viu a face do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 29, 'Mandou chamar Joab para o enviar ao rei, mas ele não quis ir. Chamou-o segunda vez, e, tendo ele recusado ir,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 30, 'disse aos seus servos: Vós sabeis que Joab tem um campo junto do meu, que está semeado de cevada; ide, pois, e lançai-lhe o fogo. Os servos de Absalão puseram fogo à seara. Indo os servos de Joab ter com seu amo, rasgadas as suas vestes, disseram-lhe: Os servos de Absalão puseram fogo a parte do teu campo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 31, 'Joab levantou-se, foi a casa de Absalão, e disse: Porque puseram os teus servos fogo à minha seara?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 32, 'Absalão respondeu a Joab: Eu mandei-te chamar, pedindo-te que viesses ter comigo, para te enviar ao rei a dizer-lhe: Por que vim eu de Gessur? Melhor me era estar lá; alcança-me pois a graça de ver a face do rei; todavia, se ele se recorda (ainda) da minha iniquidade, mande-me matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 33, 'Então Joab, apresentando-se ao rei, contou-lhe tudo. Absalão foi chamado, entrou à presença do rei, prostrou-se com a face por terra diante dele, e o rei beijou Absalão (em sinal de reconciliação completa).');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Depois disto mandou Absalão aprontar para si carros e cavaleiros, e cinqüenta homens, que andassem diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Levantava-se Absalão de manhã cedo, punha-se à entrada da porta (da cidade) e, a todo o que tinha algum negócio e vinha pedir justiça ao rei, Absalão chamava-o a si, e dizia-lhe: De que cidade és tu? Ele respondia: Eu, teu servo, sou de tal tribo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Absalão dizia-lhe: As tuas pretensões parecem-me razoáveis e justas, mas não há pessoa constituída pelo rei para te ouvir. E Absalão acrescentava:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'Oh! quem me dera ser juiz desta terra, para que viessem a mim todos os que têm negócios, e eu os decidisse segundo a justiça'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Além disso, quado se aproximava dele algum homem para o saudar, estendia a sua mão e, abraçando-o, o beijava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'Fazia isto com todos os de Israel, que vinham para que o rei os ouvisse e julgasse, e (deste modo) atraía a si o coração dos homens de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'Passados quatro anos, Absalão disse ao rei Davide: Permite-me que vá a Hebron para cumprir os votos que fiz ao Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'porque, quando o teu servo estava em Gessur da Síria, fez este voto: Se o Senhor me reconduzir a Jerusalém, eu oferecerei um sacrifício ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'O rei Davide disse-lhe: Vai em paz. Ele saiu, e foi para Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'Absalão enviou emissários por todas as tribos de israel, dizendo: Logo que ouvirdes o som da trombeta, dizei: Absalão reina em Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Com Absalão foram duzentos homens de Jerusalém, convocados por ele, que o seguiam com simplicidade do coração, sem nada saberem dos seus desígnios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'Absalão mandou também chamar Aquitofel, Gilonita, conselheiro de Davide, à sua cidade de Gilo. Enquanto imolava as vítimas, fez-se um a poderosa conjuração, e crescia o número de gente que tomava o partido de Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'Chegou pois um mensageiro a Davide, dizendo: Todo o Israel segue Absalão de todo o coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Davide disse aos seus criados, que estavam com ele em Jerusalém: Levantai-vos, fujamos, porque não poderemos escapar das mãos de Absalão; apressai-vos a sair, não suceda que ele, chegando, nos apanhe, traga sobre nós a ruína e mande passar a cidade a fio da espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Os servos do rei disseram-lhe: Nós, teus servos, executaremos de boa vontade tudo o que mandar o rei nosso senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Saiu, pois, o rei, a pé, com toda a sua família, e deixou dez das suas mulheres secundárias para guardarem o palácio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Tendo saído o rei, com todo o Israel a pé, parou, estando já longe de sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'Todos os seus servos iam aos lados dele; (porém) as legiões dos Cereteus e Felesteus, e todos os Geteus, fortes guerreiros, em número de seiscentos homens a pé, que o tinham seguido desde Get, iam adiante do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'O rei dIsse a Etai Geteu: Por que vens tu conosco? Volta, e vai viver com o (novo) rei, porque és estrangeiro, estás fora da tua terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Chegaste ontem, e hoje vou fazer que andes errante conosco, quando eu próprio ignoro para onde irei? Volta, e leva contigo os teus irmãos, e o Senhor usará contigo de misericórdia e de justiça, porque deste mostras da tua gratidão e fidelidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'Etai respondeu ao rei, dizendo: Viva o Senhor, e viva o rei meu senhor, que, em qualquer lugar em que tu te encontrares, ó rei meu senhor, quer seja na morte quer na vida, aí se encontrará o teu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'Davide disse a Etai: Vem e passa (o Cedron). Etai Geteu passou, com todos os homens que estavam com ele e com toda a sua família.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 23, 'Todos choravam em alta voz, enquanto passava o povo; e o rei também passava a torrente do Cedron, e todo o povo tomava o caminho que olha para o deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 24, 'Veio também o pontífice Sadoc, e com ele todos os levitas, que levavam a arca do Testamento de Deus. Assentaram a arca de Deus, enquanto Abiatar subia, e até que tivesse passado todo o povo que tinha saído da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 25, 'O rei disse a Sadoc: Torna a levar a arca de Deus para a cidade; se eu achar graça diante dos olhos do Senhor, ele me reconduzirá e fará que eu veja a sua arca e o seu tabernáculo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 26, 'Se ele porém me disser: Tu não me agradas eu estou pronto: faça de mim o que bem lhe parecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 27, 'O rei disse ao pontífice Sadoc: ó vidente, volta em paz para a cidade com Aquimaas, teu filho, e Jónatas, filho de Abiatar; estes vossos dois filhos estejam convosco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 28, 'Eu vou esconder-me nas campinas do deserto, até que vós me mandeis novas do estado das coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 29, 'Sadoc e Abiatar tornaram a levar para Jerusalém a arca de Deus, e lá ficaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 30, 'Entretanto Davide ia subindo a encosta do Monte das Oliveiras, e subia-a chorando, caminhando com os pés descalços e a cabeça coberta; todo o povo que ia com ele, subia também com cabeça coberta, a chorar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 31, 'Foi referido a Davide que Aquitofel também entrava na conjuração de Absalão, e David e disse: Peço-te, Senhor, que tornes insensato o conselho de Aquitofel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 32, 'Quando Davide chegou ao cume do monte, lá onde se adora o Senhor, veio ao seu encontro Chusai Araquita, com as vestes rasgadas e a cabeça coberta de pó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 33, 'Davide disse-lhe: Se vieres comigo, ser-me-ás pesado;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 34, 'mas, se voltares para a cidade e disseres a Absalão: Eu, ó rei, sou teu servo, e eu te servirei a ti, como servi a teu pai então desconcertarás (em meu favor) os conselhos de Aquitofel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 35, 'Tu tens contigo os sacerdotes Sadoc e Abiatar; tudo o que ouvires na casa do rei, o farás saber aos sacerdotes Sadoc e Abiatar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 36, 'Com eles estão os seus dois filhos, Aquimaas, filho de Sadoc, e Jónatas, filho de Abiatar; por eles me avisareis de tudo o que ouvirdes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 37, 'Chusai, amigo de Davide, voltou à cidade, ao mesmo tempo que Absalão fazia a sua entrada em Jerusalém.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Tendo Davide baixado um pouco do alto do monte, saiu-lhe ao encontro Siba, criado de Mifiboset, com dois jumentos carregados de duzentos pães, de cem penduras de uvas passas, de cem camadas de figos e de um odre de vinho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'O rei disse a Siba: Para que é isto? Siba respondeu: Os jumentos são para montarem neles os domésticos do rei; os pães e os figos, para que os comam os teus criados; o vinho, para beber dele quem se achar fraco no deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'O rei disse: Onde está o filho do teu senhor? Siba respondeu ao rei: Ficou em Jerusalém, dizendo: Hoje a casa de Israel me restituirá o reino de meu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'O rei disse a Siba: Tudo o que foi de Mifiboset é teu. Siba respondeu: O que eu desejo, ó rei meu senhor, é achar graça diante de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Quando o rei Davide chegou a Baurim, saía dali um homem da parentela da casa de Saul, chamado Semei, filho de Gera, o qual, adiantando-se, o seguia de perto e o amaldiçoava,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'atirando pedras contra Davide e contra todos os servos do rei Davide, se bem que todo o povo e todos os homens de guerra marchavam à direita e à esquerda do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Semei, amaldiçoando o rei, dizia assim: Sai, sai, homem sanguinário, homem de Belial.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'O Senhor te deu (agora) o pago de todo o sangue da casa de Saul, porquanto lhe usurpaste o reino; o Senhor o deu na mão de teu filho Absalão. Olha como os males te oprimem, porque és um homem sanguinário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Então Abisai, filho de Sarvia, disse ao rei: Por que amaldiçoa este cão morto o rei meu senhor? Eu vou e cortar-lhe-ei a cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'O rei disse: Que importa a mim e a vós, filhos de Sarvia? Deixai que amaldiçoe, porque o Senhor lhe permitiu que amaldiçoasse Davide. Quem se atreverá a dizer: Por que fez ele assim?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'O rei disse a Abisai e a todos os seus servos: Se meu filho, que eu gerei das minhas entranhas, procura tirar-me a vida, quanto mais agora um filho de Jemini! Deixai-o mal-dizer, conforme a permissão do Senhor;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'talvez o Senhor olhe para a minha aflição, e me dê bens pelas maldições deste dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'Entretanto Davide prosseguia o seu caminho acompanhado dos seus. Semei ia pelo alto, costeando o monte, perto dele, mal-dizendo-o, atirando-lhe pedras, e espalhando poeira pelo ar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Chegou enfim o rei (a Baurim), e com ele todo o povo, fatigado, e ali descansaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Entretanto Absalão e todos os do seu partido entraram em Jerusalém, e com ele também Aquitofel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'Quando Chusai Araquita, amigo de Davide, se apresentou a Absalão, disse-lhe: Deus te salve, ó rei. Deus te salve, ó rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'Absalão disse-lhe: É essa a tua gratidão para com o teu amigo? Por que não foste com o teu amigo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'Chusai respondeu a Absalão: De nenhuma sorte, porque eu hei-de ser daquele a quem o Senhor e todo este povo e todo o Israel escolheram; hei-de ficar com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'Além disso, a quem devo eu servir? Não é ao filho do rei? Como obedeci a teu pai, assim te obedecerei a ti também.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'Absalão disse a Aquitofel: Deliberai entre ambos sobre o que devemos fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 21, 'Aquitofel disse a Absalão: Abusa das mulheres secundárias de teu pai, que ele deixou para guardarem o palácio, a fim de que, constando por todo o Israel que fizeste esta afronta a teu pai, se unam mais fortemente ao teu partido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 22, 'Armaram pois para Absalão uma tenda no terraço, e ele, à vista de todo o Israel, abusou das mulheres secundárias de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 23, 'Os conselhos que Aquitofel dava naqueles dias eram considerados como oráculos de um Deus. Assim se consideravam todos os conselhos de Aquitofel, quer quando estava com Davide, quer quando estava com Absalão.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Disse pois Aquitofel a Absalão: Farei para mim escolha de doze mil homens, e sairei a perseguir Davide esta noite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'Dando sobre ele, (pois que está cansado e frouxo das mãos), o derrotarei, e, logo que fugir todo o povo que está com ele, matarei o rei abandonado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'E reconduzirei todo o povo, como se faz voltar um só homem; pois que tu a um só homem buscas; e (morto ele) todo o povo ficará em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'E o seu parecer agradou a Absalão e a todos os anciães de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'Todavia Absalão disse: Chamai Chusai Araquita, e ouçamos também o que ele diz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'Chegado Chusai à presença de Absalão, Absalão disse-lhe: Eis o conselho que Aquitofel deu; devemo-lo nós seguir ou não? Que nos aconselhas tu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'Chusai disse a Absalão: Não é bom o conselho que Aquitofel deu esta vez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'E Chusai acrescentou mais: Tu sabes que teu pai e a gente que está com ele, são uns homens valentíssimos, e que estão com o coração amargurado, como uma ursa que discorre enfurecida pelo bosque, por lhe terem roubado os cachorrinhos. Além disso teu pai é homem guerreiro, e com certeza não passará a noite com os seus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'Talvez agora esteja ele escondido nas cavernas, ou em outro qualquer lugar que tenha escolhido; se no princípio perecerem alguns (dos teus), publicar-se-á isto, e, quem ouvir, dirá: Foi derrotado o povo que seguia Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, '(Ao ouvir isto) mesmo os mais fortes, cujos corações são como de leões, desfalecerão de medo, porque todo o povo de Israel sabe que teu pai é valente, e que todos os que estão com ele são esforçados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'O conselho, pois, que me parece acertado, é este: Junte-se a ti todo o Israel, desde Dan até Bersabéa, que será inumerável como a areia do mar; e tu irás pessoalmente ao combate.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Então daremos sobre eles, em qualquer lugar em que for achado, e (sendo tantos) cobri-lo-emos, como o orvalho costuma cobrir a terra; não deixaremos nem um só homem dos que estão com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'Porém , se ele se retirar para alguma cidade, todo o Israel cingirá aquela cidade com cordas, e trazê-la-emos arrastando até à torrente, para que não fique dela nem uma pedra. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'Absalão e todos os anciães de Israel disseram: O conselho de Chusai Araquita é melhor do que o conselho de Aquitofel. Por disposição do Senhor, foi abandonado o útil conselho de Aquitofel, para que o Senhor fizesse cair o mal sobre Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Chusai disse aos pontífices Sadoc e Abiatar: Deste e deste modo aconselhou Aquitofel a Absalão e aos anciães de Israel, e eu aconselhei assim e assim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'Agora, pois, mandai a toda a pressa avisar Davide, dizendo-lhe: Não fiques esta noite nas planícies do deserto, mas passa sem demora à outra banda; não seja que fique destroçado o rei com todo o povo que está com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Ora Jónatas e Aquimaas estavam esperando junto à fonte de Rogel; uma escrava foi-lhes dar o aviso, e eles partiram a dar parte ao rei Davide, porque não deviam ser vistos, entrando na cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'Viu-os, todavia, um jovem, e avisou Absalão. Mas eles, apressando o passo, entraram em casa dum homem de Baurim, que tinha uma cisterna à entrada da casa, dentro da qual se esconderam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'A mulher da casa tomou uma coberta, e estendeu-a sobre a boca da cisterna, como quem queria secar cevada pilada, e assim a coisa ficou oculta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Tendo chegado àquela casa os servos de Absalão, disseram à mulher: Onde estão Aquimaas e Jónatas? A mulher respondeu-lhe: Foram-se apressadamente, depois de beberem um pouco de água. Eles procuraram-nos, mas, não os tendo encontrado, voltaram para Jerusalém .'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'Logo que se retiraram, Aquimaas e Jónatas saíram da cisterna e, continuando o seu caminho, avisaram o rei Davide, dizendo-lhe: Marchai e passai depressa o rio, porque Aquitofel deu este conselho contra vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'Davide levantou-se e toda a sua gente que estava com ele, e passaram o Jordão antes de amanhecer; não ficou nem um só, que não passasse o rio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'Aquitofel porém, vendo que se não tinha seguido o seu conselho, aparelhou o seu jumento, levantou-se, foi para sua casa e para a sua cidade, e, tendo disposto todos os negócios da sua casa, enforcou-se; morto, foi sepultado no sepulcro de seu pal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'Davide chegou aos acampamentos, e Absalão passou o Jordão, com todos os homens de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 25, 'Absalão tinha dado o mando do exército a Amasa, lugar que era de Joab. Amasa era filho de um homem de Jezrael, chamado Jetra, que era casado com Abigail, filha de Naás, irmã de Sarvia, que foi mãe de Joab.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 26, 'Israel acampou com Absalão no país de Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 27, 'Tendo Davide chegado ao acampamento, Sobi, filho de Naás, de Raba dos Amonitas, e Maquir, filho de Amiel de Lodabar, e Berzelai Galaadita de Rogelim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 28, 'ofereceram-lhe camas, tapetes, louça de barro, trigo e cevada, farinha, grão torrado, favas, lentilhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 29, 'mel, manteiga, ovelhas e novilhos gordos; deram (tudo isto) a Davide e ao povo que estava com ele, para que comessem, persuadidos de que o povo estaria quebrantado de fome e de sede no deserto.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Davide, tendo feito resenha da sua gente, nomeou sobre ela chefes de milhar e chefes de centena.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Pôs um terço das suas tropas sob o mando de Joab, outro terço sob o mando de Abisai, filho de Sarvia irmão de Joab, e outro terço sob o mando de Etai de Get. O rei disse ao povo: Eu sairei também convosco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'Todavia o povo respondeu: Não sairás, porque, ainda que os inimigos nos ponham em fuga, não terão isto por uma grande coisa; mesmo que morra metade de nós, não lhes dará isso maior cuidado. Tu, porém és considerado como dez mil. Logo é melhor que fiques na cidade para nos socorrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'O rei disse-lhes: Farei o que vos parecer bem. E pôs-se o rei junto à porta (da cidade), e o povo Ia desfilando, formado em esquadrões de cem e de mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'O rei deu esta ordem a Joab, a Abisai e a Etai: Poupai-me o meu filho Absalão. E todo o povo ouviu a ordem que o rei dava a todos os seus generais em favor de Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'Saiu, enfim , o povo à campanha contra Israel, e deu-se a batalha no bosque de Efraim'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'Ali o povo de Israel foi derrotado pelo exército de Davide, e naquele dia houve um a grande mortandade de vinte mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'O combate estendeu-se sobre a superfície de toda aquela terra, e foram muito mais os que pereceram (fugindo) pelo bosque, do que aqueles que pereceram à espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Ora aconteceu que, indo Absalão montado num macho, se encontrou com a gente de Davide. Tendo entrado o macho por baixo dum frondoso e grande carvalho, enredou-se a cabeleira (de Absalão) nos ramos do carvalho; pasando adiante o macho em que la montado, ficou ele pendurado entre o céu e a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'Vendo isto um homem, avisou Joab, dizendo: Eu vi Absalão pendurado dum carvalho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'Joab disse ao homem que lhe dava esta notícia: Se o viste, por que o não abateste? Eu dar-te-ia dez siclos de prata e um cinto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'Ele respondeu a Joab: Ainda que pusesses nas minhas mãos mil siclos de prata, de nenhuma sorte estenderia minha mão contra o filho do rei, porque todos nós ouvimos a ordem que o rei deu a ti, a Abisai, e a Etai, quando disse: Poupai-me o meu filho Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'Se eu, com risco da minha vida, tivesse procedido tão temerariamente, de nenhum modo isto se poderia ocultar ao rei; e tu mesmo opor-te-ias (ao rei, defendendo-me)?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Joab disse: Não será o que dizes, mas à tua vista o matarei. Tomou, pois, na mão três langas, e traspassou com elas o coração de Absalão. Quando ele ainda palpitava pendurado no carvalho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'correram dez jovens escudeiros de Joab, que, a golpes, o acabaram de matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'Joab tocou a trombeta, e, querendo poupar a multidão (dos vencidos). Impediu que a sua gente fosse no alcance dos Israelitas que fugiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'Tomaram Absalão, lançaram-no numa grande cova no bosque, e arremessaram sobre ele um grandíssimo montão de pedras. Todos os Israelitas fugiram para as suas tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'Absalão, quando ainda vivia, tinha feito levantar para si um monumento no vale do Rei, porque tinha dito: Eu (já) não tenho filhos, e este será uma memória do meu nome. E deu o seu nome a este monumento, o qual ainda hoje se chama a Mão de Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'Aquimaas, filho de Sadoc, disse: Deixa-me correr a levar ao rei a boa notícia de que o Senhor lhe fez justiça (libertando-o) do poder de seus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'Joab disse-lhe: Não lhe levarás hoje a notícia, mas outro dia; não quero que lha leves hoje, porque morreu o filho do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'Joab disse a um cusita: Parte e vai anunciar ao rei o que viste. Ele fez-lhe uma profunda reverência e partiu a correr.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Aquimaas, filho de Sadoc, disse novamente a Joab: Que embaraço há para que eu não vá também correndo atrás do cusita? Joab respondeu-lhe: Por que queres tu correr, ó meu filho? Esta mensagem não te aproveitaria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, '(Aquimaas) respondeu: Seja o que for, eu correrei. Joab disse-lhe: Corre. Correndo, pois, Aquimaas por um atalho, passou adiante do cusita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'Davide estava sentado entre as duas portas. A sentinela que estava por cima da porta, sobre a muralha, levantando os olhos, viu vir um homem correndo sozinho e gritou para advertir o rei. O rei respondeu: Se vem só, traz alguma boa nova. Entretanto, apressando-se ele e estando já próximo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, '.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'a sentinela descobriu outro homem que corria, e, gritando de cima, disse: Eu vejo lá vir correndo outro homem só. O rei disse: Também este traz alguma boa nova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'A sentinela disse: Observo que o modo de correr do primeiro me parece ser o correr de Aquimaas, filho de Sadoc. O rei disse: É um homem de bem, e vem (certamente) trazer boas novas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Aquimaas, gritando, disse ao rei: Vitória! E, prostrado em terra, diante do rei, e fazendo-lhe uma profunda reverência; disse: Bem-dito seja o Senhor, teu Deus, que destroçou os homens que se tinham sublevado contra o rei, meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 29, 'O rei disse: Está vivo o meu filho Absalão? Aquimaas respondeu-lhe: Quando o teu servo Joab me enviou a ti, que (também) sou teu servo, ó rei, eu vi um grande tumulto; não sei mais nada. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 30, 'O rei disse-lhe: Afasta-te e espera aí. Tendo ele passado e estando no seu lugar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 31, 'chegou o cusita que disse: Ó rei, meu senhor, trago-te um a boa nova, porque o Senhor julgou hoje em teu favor, libertando-te da mão de todos aqueles que se sublevaram contra ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 32, 'O rei disse ao cusita: Está vivo o meu filho Absalão? Cusi, respondendo-lhe, disse: Assim suceda aos inimigos do rei, meu senhor, e a todos os que se sublevam contra ele para o perderem, como sucedeu àquele jovem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 33, 'Então o rei, cheio de tristeza subiu ao quarto, que estava por cima da porta, e pôs-se a chorar. E, andando, dizia assim: Meu filho Absalão! Absalão, filho meu! Quem me dera ter morrido por ti, Absalão, meu filho, filho meu, Absalão');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'Noticiaram a Joab que o rei chorava e lamentava o seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'A vitória converteu-se em luto naquele dia para todo o povo, porque o povo ouviu dizer naquele dia: O rei chora o seu filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'O povo absteve-se, aquele dia, de entrar na cidade, como costuma abster-se um povo derrotado e que foge da batalha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'Mas o rei cobriu a cabeça, e dizia em alta voz: Filho meu Absalão, Absalão filho meu, filho meu!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Joab, entrando no quarto onde estava o rei, disse (com a sua costumada altivez): Tu hoje cobriste de confusão todos os teus servos, que salvaram a tua vida, a vida de teus filhos e filhas, a vida de tuas esposas e a vida de tuas mulheres secundárias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Amas os que te aborrecem, e aborreces os que te amam, pois hoje mostraste que se te não dá nem dos teus oficiais nem dos teus criados; na verdade, conheci agora que, se Absalão vivesse, ainda que todos nós tivéssemos morrido, ficarias contente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'Agora, pois, levanta-te, sai e fala com o coração a teus servos, porque eu te juro pelo Senhor que, se não saíres, nem sequer um homem ficará contigo esta noite; isto será para ti pior do que todos os males que têm vindo sobre ti desde a tua mocidade até ao presente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'O rei levantou-se e sentou-se à porta. Avisou-se todo o povo de que o rei estava sentado à porta, e toda a multidão foi apresentar-se diante do rei. Os de Israel, porém, tinham fugido para as suas tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Todo o povo, em todas as tribos de Israel, discutia, dizendo; O rei livrou-nos da mão de nossos inimigos, salvou-nos do poder dos Filisteus, e agora fugiu da sua terra por causa de Absalão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'Ora Absalão, a quem tínhamos ungido por nosso rei, morreu na batalha; por que esperais, e não fazeis voltar o rei?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'O rei Davide mandou dizer aos sacerdotes Sadoc e Abiatar: Falai aos anciães de Judá e dizei-lhes: Por que sois vós os últimos a convidar o rei a ir para sua casa? (Com efeito, tinham chegado ao conhecimento do rei, em sua casa, as palavras de todo o Israel).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'Vós sois meus Irmãos, o meu osso e a minha carne; por que sois os últimos a fazer voltar o rei?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'Dizei a Amasa: Não és tu o meu osso e a minha carne? Deus me trate com todo o seu rigor, se eu te não fizer para sempre general do meu exército junto à minha pessoa, em lugar de Joab.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, '(Deste modo) ganhou o coração de todos os de Judá, de maneira que como se fossem um só homem, mandaram dizer ao rei; Volta com todos os teus servos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'O rei voltou e chegou até no Jordão, e todos os de Judá vieram até Galgala, para irem ao encontro do rei e o acompanharem na passagem do Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'Também Semei, natural de Baurim, filho de Gera, filho de Jemíni, foi a toda a pressa com os de Judá ao encontro do rei Davide,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'com mil homens de Benjamim, e Siba, servo da casa de Saul, com quinze filhos seus e vinte servos na sua companhia, os quais, metendo-se pelo Jordão diante do rei,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'passaram o vau, para fazerem atravessar a família do rei e para executarem as suas ordens. Semei, filho de Gera, prostrado diante do rei, quando este já tinha passado o Jordão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'disse-lhe: Não castigues, meu senhor, a minha maldade, nem te lembres das injúrias do teu servo, meu rei e senhor, no dia em que saíste de Jerusalém, nem as conserves, ó rei, no teu coração,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 20, 'porque eu, teu servo, conheço o meu pecado, e por isso vim hoje, o primeiro de toda a casa de José, a receber o rei, meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 21, 'Respondendo, porém, Abisai, filho de Sarvia, disse: Porventura bastarão estas palavras para Semei não ser morto, depois de ter amaldiçoado o ungido do Senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 22, 'Mas Davide disse: Que tenho eu convosco, ó filhos de Sarvia? Por que vos haveis de opor, hoje, a mim? Então há-de, neste dia, tirar-se a vida a um israelita? Ignoro eu porventura que hoje fui feito rei sobre Israel?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 23, 'E o rei disse a Semei: Não morrerás. E assim lho jurou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 24, 'Veio Mifiboset, filho de Saul, receber o rei. Não havia lavado os pés nem feito a barba, nem lavado vestes desde o dia em que o rei tinha saído, até ao dia da sua volta em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 25, 'Vindo ao encontro do rei em Jerusalém , o rei disse-lhe: Mifiboset, por que não foste tu comigo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 26, 'Ele respondeu-lhe: Meu rei e senhor, o meu criado enganou-me porque eu, teu servo, disse-lhe que me aparelhasse um jumento para montar nele, e ir com o rei, pois eu, teu servo, sou coxo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 27, 'Ele, além disto, acusou-me a mim, teu servo, diante de ti, meu rei e senhor, mas tu, meu rei e senhor, és como um anjo de Deus: faze o que bem te parecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 28, 'A casa de meu pai não mereceu do rei, meu senhor, senão a morte; porém tu me puseste a mim, teu servo, entre os que comem à tua mesa; de que poderei eu, pois, queixar-me com justiça? como poderei eu importunar mais o rei (com pedido)?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 29, 'O rei disse-lhe: Para que tantas palavras? O que eu mandei, há-de subsistir; tu e Siba reparti as terras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 30, 'Mifiboset respondeu ao rei: Fique ele muito embora com tudo, uma vez que o rei, meu senhor, voltou em paz a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 31, 'Também Berzelai de Galaad, tendo vindo de Rogelim acompanhou o rei na passagem do Jordão, pronto a segui-lo ainda da outra banda do rio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 32, 'Berzelai de Galaad era muito velho, isto é, de oitenta anos, e tinha provido o rei de víveres, quando estava em Maanaim, porque era um homem muito rico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 33, 'O rei disse a Berzelai: Vem comigo, para viveres em minha companhia, descansado, em Jerusalém'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 34, 'Mas Berzelai disse ao rei: Quantos anos me restam de vida, para subir com o rei a Jerusalém?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 35, 'Tenho hoje oitenta anos. Porventura ainda posso discernir entre o bom e o mau? Pode o teu servo perceber sabor no que come e no que bebe? Posso ouvir ainda a voz dos cantores e das cantoras? Por que há-de o teu servo servir de peso ao rei, meu senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 36, 'Eu, teu servo, acompanhar-te-ei ainda um pouco da outra banda do Jordáo. E por que me há-de conceder o rei tal recompensa?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 37, 'Rogo-te que permitas a mim, teu servo, voltar e morrer na minha cidade, e ser sepultado junto do sepulcro de meu pai e de minha mãe. Aqui está Camaam (meu filho e) teu servo; vá ele contigo, ó meu rei e senhor, e faze dele o que for mais do teu agrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 38, 'O rei disse-lhe: Venha comigo Camaam, que eu lhe farei tudo o que quiseres, e conceder-te-ei tudo o que me pedires.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 39, 'Quando todo o povo e o rei acabaram de passar o Jordão, o rei beijou Berzelai e abençoou-o, e ele voltou para sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 40, 'Passou então o rei a Galgala, e a Camaam com ele. Ora todo o povo de Judá tinha acompanhado o rei ao passar do rio, mas só se tinha encontrado ali metade do povo de Israel'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 41, 'Por isso todos os de Israel, acudindo juntos ao rei, disseram-lhe: Por que se apoderaram de ti os nossos irmãos, os homens de Judá, e fizeram passar o Jordão o rei e toda a gente de Davide com ele? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 42, 'E todos os homens de Judá responderam aos homens de Israel: É porque o rei nos toca a nós mais de perto; por que vos irais por isso? Porventura comemos nós alguma coisa do rei, ou foram-nos dados alguns presentes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 43, 'Respondendo os homens de Israel aos de Judá, disseram: Nós somos dez vezes mais do que vós para servir o rei, por isso Davide pertence mais a nós do que a vós; por que nos fizestes este agravo, e não fomos avisados antes, para fazermos voltar o nosso rei? Porém, os homens de Judá responderam mais duramente ainda que os de Israel.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'Aconteceu encontrar-se ali um homem perverso, chamado Seba, filho de Bocri, da cidade de Jemini, o qual tocou a trombeta, e disse: Nós não temos parte alguma com Davide, nem herança com o filho de Isaí; volta para as tuas tendas, Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'E todo o Israel separou-se de Davide, e seguiu Seba, filho de Bocri. Todavia os de Judá não se separaram do seu rei, desde o Jordão até Jerusalém'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'O rei, depois que chegou ao seu palácio de Jerusalém, tomou as dez mulheres secundárias, que ele tinha deixado a guardar (a casa), e pô-las em clausura, dando-lhes com que se alimentassem. Não se chegou mais a elas, mas ficaram encerradas, vivendo como viúvas até ao dia da sua morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'O rei disse a Amasa: Faze-me vir dentro de três dias todos os (soldados) de Judá, e está presente com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Partiu, pois, Amasa para juntar os (soldados) de Judá, mas tardou além do praso que o rei lhe tinha fixado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'Davide disse a Abisai: Agora Seba, filho de Bocri, afligir-nos-á muito mais do que Absalão; portanto toma os servos de teu senhor, e vai em seu alcance, não suceda que ele encontre cidades fortes e nos escape.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'Saíram, pois, com ele os homens de Joab, e também os Cereteus e os Feleteus; Igualmente todos os homens mais valentes de Jerusalém saíram, para perseguirem Seba, filho de Bocri.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Quando eles estavam Junto da grande pedra, que há em Gabaon, saiu-lhes ao encontro Amasa. Joab estava vestido com uma túnica estreita, que lhe ficava justa ao corpo, e sobre ela levava cingida a espada, pendente até às ilhargas, dentro da sua bainha, a qual tinha sido feita como tal arte, que num momento podia sair e ferir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 9, 'Disse Joab a Amasa: A paz seja contigo, meu irmão. E com a mão direita tomou Amasa pela barba como para o beijar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 10, 'Amasa não reparou na espada que Joab trazia, e este feriu-o no ventre, lançando-lhe por terra os intestinos; sem ser necessário segundo golpe, Amasa caiu morto. Joab e Abisai, seu irmão, marcharam contra Seba, filho de Bocri.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 11, 'Entretanto um dos companheiros de Joab, parando junto ao cadáver de Amasa, disse: Quem é por Joab e por Davide, que siga a Joab.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 12, 'Amasa estava estendido no meio do caminho, todo coberto de sangue. O tal homem, vendo que todo o povo parava a vê-lo, tirou-o do caminho para o campo, e cobriu-o com um manto, para que, os que passavam , não parassem junto dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 13, 'Quando, pois, foi tirado do caminho, passaram todos os que iam com Joab no alcance de Seba, filho de Bocri.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 14, 'Este tinha atravessado todas as tribos de Israel até Abel-Bet-Maca, e tinham-se-lhe juntado todos os homens escolhidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 15, 'Foram, então, e sitiaram-no em Abel-Bet-Maca, e levantaram um baluarte contra a cidade, que ficou esta sitiada; toda a gente que estava com Joab esforçava-se por fazer cair os muros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 16, 'Uma mulher prudente da cidade gritou: Ouvi, ouvi, dizei a Joab: Aproxima-te daqui, e eu te falarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 17, 'Tendo-se ele aproximado, disse-lhe a mulher: Tu és Joab? Ele respondeu: Sou. Ela falou-lhe assim: Ouve as palavras de tua escrava. Ele respondeu-lhe: Ouço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 18, 'A mulher prosseguiu: Noutro tempo costumava-se dizer: Os que buscam conselho, peçam-no a Abel e assim concluíam os seus negócios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 19, 'Eu sou uma cidade pacifica e fiel em Israel; tu queres arruinar uma cidade, que é uma mãe em Israel? Por que te afadigas tu em destruir a herança do Senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 20, 'Joab respondeu, dizendo: Longe, longe de mim, que eu tal faça; eu não venho arruinar nem destruir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 21, 'Não é essa a minha intenção, mas busco um homem do monte de Efraim, chamado Seba, filho de Bocri, que se levantou contra o rei Davide; entregai-nos só este, e retirar-nos-emos da cidade. A mulher disse a Joab: Agora mesmo te será lançada a sua cabeça pelo muro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 22, 'Ela, pois, foi ter com todo o povo, falou-lhes sabiamente; eles, cortada a cabeça de Seba, filho de Bocri, atiraram-na a Joab. Joab tocou a trombeta, e retiraram-se da cidade, cada um para as suas tendas; Joab voltou a Jerusalém, e foi ter com o rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 23, 'Deste modo ficou Joab general de todo o exército de Israel; Benaias, filho de Jojada, comandava os Cereteus e os Feleteus;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 24, 'Aduram era superintendente dos tributos; Josafat, filho de Ailud, cronista-mor;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 25, 'Siva era secretário; Sadoc e Ablatar, pontífices;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 26, 'Ira de Jair, conselheiro íntimo de Davide.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Houve também no tempo de Davide uma fome que durou três anos contínuos. Davide consultou o oráculo do Senhor, e o Senhor respondeu-lhe: (Isto aconteceu) por causa de Saul e da sua casa sanguinária, porque matou os Gabaonitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'E, chamados os Gabaonitas, o rei falou com eles. (Deve notar-se que os Gabaonitas não eram filhos de Israel, mas uns restos dos Amorreus, aos quais os Israelitas tinham jurado (que não lhes tirariam a vida). Todavia Saul empreendeu extingui-los sob pretexto de zelo, como para bem dos filhos de Israel e de Judá).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'Disse, pois, Davide aos Gabaonitas: Que quereis que eu vos faça? Que satisfação vos darei, para que abençoeis a herança do Senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'Os Gabaonitas responderam-lhe: Não é nossa pretensão sobre ouro nem prata, senão contra Saul e contra a sua casa; nem queremos que seja morto nenhum homem de Israel. O rei disse-se-lhes: Que quereis, pois, que eu vos faça?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'Eles responderam ao rei: Aquele homem que iniquamente nos esmagou e oprimiu, nós o devemos exterminar, de tal modo que não fique da sua linhagem nem um só em todos os limites de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'Sejam-nos dados (ao menos) sete de seus filhos para os crucificarmos diante do Senhor em Babaa, (pátria) de Saul, que foi noutro tempo o escolhido do Senhor. O rei disse: Eu os darei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'O rei não entregou a Mifiboset, filho de Jónatas, filho de Saul, por causa do juramento (firmado em nome) do Senhor, que tinha sido feito entre Davide e Jónatas, filho de Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Tomou os dois filhos de Resfa, filha de Aia, chamados Armoni e Mifiboset, os quais ela tinha tido de Saul, e cinco filhos, que Micol, filha de Saul, tinha gerado a Hadriel, filho de Berzelai, que era de Molati,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'e entregou-os nas mãos dos Gabaonitas, que os crucificaram no monte diante do Senhor. Assim acabaram estes sete homens, mortos todos juntos nos primeiros dias da ceifa, quando se começavam a segar as cevadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'Resfa, filha de Aia, tomando um pano de cilício, estendeu-o debaixo de si, sobre uma pedra, (e esteve ali) desde o princípio da ceifa até que a água do céu caiu sobre (os cádáveres), e não deixou que as aves os despedaçassem de dia, nem as feras de noite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Foi contado a Davide o que tinha feito Resfa, filha de Aia, mulher secundária de Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Davide foi, e tomou, os ossos de Saul e de Jónatas, seu filho, (recebendo-os) dos homens de Jabes de Galaad, que os tinham tirado furtivamente da praça de Betsan, na qual os Filisteus os tinham pendurado, quando mataram Saul em Gelboé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'Davide transportou dali os ossos de Saul e de Jónatas, seu filho, mandou também recolher os ossos dos que tinham sido crucificados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Foi-lhes dada sepultura com os ossos de Saul e de Jónatas, seu filho, na terra de Benjamim, a um lado do sepulcro de Cis seu pai, em cumprimento de todas as ordens do rei. Depois disto, Deus compadeceu-se da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Ateou-se, porém, de novo a guerra dos Filisteus contra Israel, e Davide saiu com sua gente, e combateram contra os Filisteus. Estando Davide cansado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'Jesbilbenob, que era da linhagem de Arafa, que ia armado duma lança, cujo ferro pesava trezentas onças, e que cingia uma espada nova, esforçou-se por ferir Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'Abisai, filho de Sarvia, defendeu-o, e, ferindo o Filisteu, o matou. Então os soldados de Davide fizeram um juramento, dizendo: Tu não tornarás a sair à batalha conosco, para que não apagues a lâmpada de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'Houve ainda uma segunda guerra em Gob contra os Filisteus, na qual Sobocai, de Husati, matou Saf, da linhagem de Arafa, da raça dos gigantes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'Houve mais outra terceira guerra em Gob contra os Filisteus, na qual Adeodato, filho de Salto, que tecia panos de cores em Belém, matou Golias de Get, que levava uma lança, cuja haste era como um cilindro de tear.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'A quarta guerra foi em Get. Nela se encontrou um homem de grande estatura, que tinha seis dedos em cada mão e em cada pé, isto é, vinte e quatro dedos, e era da raça de Arafa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Este blasfemou contra Israel, mas matou-o Jonatan, filho de Semaa, irmão de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'Estes quatro homens tinham nascido da estirpe de Arafa em Bet, e foram mortos pelas mãos de Davide e da sua gente.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Davide dirigiu ao Senhor as palavras deste cântico, no dia em que o Senhor o livrou da mão de todos os seus inimigos, e da mão de Saul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 2, 'Disse: O Senhor é o meu rochedo, a minha fortaleza, o meu Salvador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'Deus é a minha defesa, nele esperarei. É o meu escudo e o sustentáculo da minha salvação. Ele me exalta e é o meu refúgio. Ó meu Salvador, tu me livraste da iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 4, 'Eu invoquei o Senhor digno de louvor, e fui salvo dos meus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'Já me cercaram as ondas da morte, as torrentes de Belial me atemorizavam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Já as cordas do inferno me cingiam, os laços da morte me apanhavam descuidado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'Na minha tribulação invocava o Senhor, e clamava ao meu Deus. Ele, do seu templo ouviu a minha voz, o meu clamor chegou aos seus ouvidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'A terra comoveu-se e estremeceu, os fundamentos dos montes foram agitados e abalados, porque (o Senhor) se irou contra eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'O fumo (da ira) dos seus narizes elevou-se ao alto, um fogo devorador saía da sua boca, carvões ardentes acesos por ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'Baixou (ou fez inclinar) os céus e desceu, e (tinha) uma escuridão debaixo de seus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'E subiu sobre os querubins, e voou; voou sobre as asas dos ventos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'Cercou-se de trevas como duma tenda, de águas escuras, nuvens espessas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'Pelo esplendor da sua presença acenderam-se carvões de fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'O Senhor trovejou do céu, e o Altíssimo fez soar a sua voz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'Disparou setas, e dissipou-os, raios, e destrui-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'E apareceram os abismos do mar, e ficaram a descoberto os fundamentos da terra às ameaças do Senhor, ao sopro do vento do seu furor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'Estendeu a sua mão do alto, e recebeu-me, e tirou-me das grandes águas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'Livrou-me do meu inimigo poderosíssimo, e daqueles que me tinham ódio, quando eram mais do que eu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'Assaltaram-me no dia da minha tribulação, mas o Senhor fez-se o meu firme esteio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 20, 'Pôs-me a salvo, livrou-me, porque se agradou de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 21, 'O Senhor me retribuiu segundo a minha justiça, e me deu segundo a pureza das minhas mãos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 22, 'porque segui os caminhos do Senhor, e não procedi impiamente, separando-me do meu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 23, 'Todos os seus mandamentos estavam diante dos meus olhos, e não me afastava dos seus preceitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 24, 'Era irrepreensível para com ele, e guardava-me da minha iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 25, 'O Senhor me retribuiu segundo a minha justiça, e segundo a pureza de minhas mãos diante dos seus olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 26, 'Com o misericordioso (ó Deus) mostras-te misericordioso, e com o íntegro, íntegro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 27, 'Com o puro mostras-te puro, e com o perverso procedes segundo a sua perversidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 28, 'Salvas o povo humilde e com os teus olhos humilhas os soberbos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 29, 'Tu, Senhor, és a minha luz, Tu, ó Senhor, alumias as minhas trevas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 30, 'Contigo, pois, corro armado a combater, com o meu Deus assalto muralhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 31, 'O caminho de Deus é imaculado, a palavra do Senhor é purificada com o fogo; é o escudo de todos os que esperaram nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 32, 'Quem é Deus senão o Senhor? E quem é forte senão o nosso Deus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 33, 'O Deus que me cingiu de fortaleza, e tornou plano e perfeito o meu caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 34, 'Que tornou os meus pés (velozes) semelhantes aos dos veados, e me colocou no lugar elevado em que me encontro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 35, 'Que adestra as minhas mãos para a peleja, e os meus braços para o arco de bronze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 36, 'Tu me deste o escudo da tua salvação, e a tua benignidade me engrandeceu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 37, 'Alargaste os meus passos debaixo de mim, e não desfalecem os meus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 38, 'Persegui os meus inimigos, e exterminei-os e não tornei atrás antes dos os desbaratar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 39, 'Consumi-os, despedacei-os de forma que não se levantaram: caíram debaixo dos meus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 40, 'Tu me cingiste de força para o combate, fizeste curvar debaixo de mim os que me resistiam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 41, 'Fizeste que voltassem as costas os meus inimigos, aqueles que me aborreciam, para os exterminar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 42, 'Clamam, e não hã ninguém que os socorra, clamam ao Senhor, e ele os não responde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 43, 'Dissipei-os como pó da terra, calquei-os e desfi-los como lodo das ruas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 44, 'Tu me salvaste das contradições do meu povo; conservaste-me para ser o chefe das nações; um povo, que eu não conhecia, me serviu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 45, 'Os estrangeiros fingem-se submissos, à menor palavra minha, me obedecem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 46, 'Os filhos estranhos foram dispersos, saíam, a tremer, dos seus esconderijos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 47, 'Viva o Senhor, e seja bem-dito o meu Deus, seja exaltado o Deus forte da minha salvação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 48, 'Tu és, ó Deus, que me vingas e que me sujeitas os povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 48, 'Tu és, ó Deus, que me vingas e que me sujeitas os povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 49, 'Tu o que me tiras dentre os meus inimigos, o que me exaltas sobre os que me resistem, e me livras do homem iníquo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 50, 'Por isso, Senhor, louvar-te-ei no meio das nações, e entoarei cânticos em honra do teu nome;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 51, 'A ti, que dás grandes vitórias ao teu rei, e usas de misericórdia com Davide, teu ungido, e com a sua descendência para sempre.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Estas são as últimas palavras de Davide: Oráculo de Davide, filho de Isaí, oráculo do homem posto nas alturas, do ungido do Deus de Jacob, do doce cantor de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'O espírito do Senhor falou por mim e a sua palavra (fez-se ouvir) pela minha língua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'O Deus de Israel me falou, o forte de Israel falou: Um justo dominador dos homens, dominador no temor de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'é como a luz da aurora que resplandece ao sair do sol, numa manhã sem nuvens. Pelos seus raios a erva brota da terra, depois das chuvas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'A minha casa não era tal diante de Deus, que ele devesse fazer comigo uma aliança eterna, firme em tudo e imutável. Toda a minha salvação e todo o meu desejo, Deus não os fará germinar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'Mas os prevaricadores serão arrancados todos como espinhos, que não se tocam com as mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Se alguém quiser tocá-los, armar-se-á (antes) de ferro ou dum pau de lança; a seguir, serão queimados até não ficar nada deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'Eis os nomes dos valentes de Davide: Jesbaam, filho de Hachamoni, chefe dos Três. Foi ele que levantou a sua lança contra oitocentos homens, que abateu numa só investida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'Depois deste, Eliazar Aoita, filho de Dodo, um dos três valentes, que se acharam com Davide em Efes-Dammin, quando desafiaram os Filisteus que se juntaram ali para a batalha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'Tendo fugido os Israelitas, Eliazar permaneceu firme e bateu os Filisteus até lhe cansar a mão, e ficar pegada à espada. Concedeu o Senhor naquele dia uma assinalada vitória, e o povo, que tinha fugido, voltou ao lugar onde estava Eleázaro, mas apenas teve que recolher os despojos dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'Depois deste, Sema, filho de Age, de Arari. Os Filisteus juntaram-se (um dia) num sítio, onde havia um campo cheio de lentilhas; fugindo o povo diante dos Filisteus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'ele pôs-se firme no meio do campo, defendeu-o, e derrotou os Filisteus, operando assim, o Senhor, por meio dele, uma grande vitória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'E já antes tinham descido estes três, que eram os principais dos trinta, a encontrar-se no tempo das messes com Davide, na cova de Odolão, quando os Filisteus haviam assentado o seu arraial no vale dos Gigantes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, 'Davide estava num lugar forte. Nesse mesmo tempo havia em Belém uma guarnição de Filisteus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'Ora Davide teve um desejo; disse: Oh! se alguém me desse a beber água da cisterna que há em Belém, junto à porta!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'No mesmo instante estes três valentes romperam pelo acampamento dos Filisteus foram tirar água à cisterna de Belém, que estava junto à porta, e trouxeram-na a Davide, mas ele não a quis beber; ofereceu-a ao Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 17, 'dizendo: Guarde-me o Senhor que tal faça: beberei eu o sangue destes homens, que foram (buscá-la) com risco das suas vidas? Não quis pois bebê-la. Tal acção foi feita por estes três fortíssimos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 18, 'Abisai, irmão de Joab, filho de Sarvia, era o primeiro dos trinta; este é o que levantou a sua lança contra trezentos, que matou, ganhando grande renome entre os trinta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 19, 'Era o mais considerado entre os trinta, e seu chefe, mas não igualara os três primeiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 20, 'Banaias de Cabseel, filho de Jojada, que foi um homem valentíssimo, e de grandes feitos, matou os dois filhos de Ariel de Moab, e ele mesmo desceu e matou um leão no meio duma cisterna, em tempo de neve.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 21, 'Foi também ele que matou um Egípcio, homem digno de ser visto, que tinha uma lança na mão. Indo contra ele com um pau, arrancou à força a lança da mão do Egípcio, e matou-o com a sua própria lança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 22, 'Isto é o que fez Banaias, filho de Jojada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 23, 'Ele era afamado entre os trinta valentes, afamado entre eles, mas não Igualava os três primeiros. Davide tinha-o feito seu conselheiro íntimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 24, 'Entre os trinta (contavam-se) Asael, irmão de Joab; Eleanan de Belém, filho de Dodo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 25, 'Sema de Harodi; Elica de Harodi;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 26, 'Heles de Falto; Hira de Tecua, filho de Aces;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 27, 'Abiezer de Anatot; Mobonai de Husati;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 28, 'Selmon de Ahot; Maaral de Netofat;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 29, 'Heled, filho de Baana, que também era de Netofat: Itai, filho de Ribai de Gabaat, da tribo de Benjamim'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 30, 'Banaia de Faraton; Hedal da torrente de Gaas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 31, 'Abialbon de Araba, Azmavet de Beromi;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 32, 'Ellaba de Salaboni; os filhos de Jassen; Jonatan;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 33, 'Sema de Orori; Ajam de Aror, filho de Sarar;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 34, 'Eliflet, filho de Aasbai, filho dum Macatiano; Eliam, filho de Aquitofel de Gelon;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 35, 'Hesral do Carmelo, Faral de Arbi;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 36, 'Igaal, filho de Natan; de Soba; Boni de Gadi;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 37, 'Selec de Amoni; Naarai de Berot, escudeiro de Joab, filho de Sarvia'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 38, 'Ira de Jetrit; Gareb também de Jetrit;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 39, 'Urias Heteu. Ao todo trinta e sete.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'O furor do Senhor tornou-se de novo a acender contra Israel e excitou David e contra ele, permitindo que dissesse (cheio de vaidade): Vai e faze o recenseamento de Israel, e de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 2, 'Disse, pois, Davide a Joab, general do seu exército; Percorre todas as tribos de Israel, desde Dan até Bersabé, e faze o recenseamento do povo, para eu saber o seu número.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'Joab respondeu ao rei; O Senhor teu Deus queira multiplicar o teu povo outro tanto do que agora é, e ainda cem vezes mais aos olhos do rei meu senhor, mas, que pretende o rei meu senhor com isto?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'Todavia a ordem do rei prevaleceu sobre as representações de Joab e dos generais do exército. Então saiu Joab da presença do rei com os primeiros oficiais do exército, a contar o povo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Tendo eles passado o Jordão, foram a Aroer, ao lado direito da cidade que está no vale de Gad'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'foram até Jazer, passaram a Galaad e à terra baixa de Hodsl, e chegaram aos bosques de Dan. Caminhando pelo contorno de Sidónia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'passaram perto das muralhas de Tiro, e por toda a terra dos Heveus e dos Cananeus, chegando até Bersabé, parte meridional de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'Tendo percorrido todo o país, voltaram a Jerusalém, depois de nove meses e vinte dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'Deu Joab ao rei a lista do povo; acharam-se em Israel oitocentos mil homens robustos, capazes de puchar pela espada, e em Judá, quinhentos mil combatentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'Depois que foi contado o povo, sentiu Davide um remorso no seu coração. Disse Davide ao Senhor: Eu cometi nesta acção um grande pecado, mas rogo-te, ó Senhor, que perdoes a iniquidade do teu servo, porque procedeu muito nèsciamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'Quando Davide se levantou, pela manhã, o Senhor dirigiu a sua palavra a Gad, profeta e vidente de Davide, dizendo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'Vai e dize a Davide: Eis o que diz o Senhor: De três coisas (para castigo) se te dá opção; escolhe qual destas queres que te mande.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'Gad, tendo-se apresentado a Davide, deu-lhe a conhecer a ordem do Senhor, dizendo: Ou virá a fome durante sete anos à tua terra; ou durante três meses irás fugindo dos teus inimigos, que te perseguirão; ou pelo menos haverá peste na tua terra durante três dias. Delibera, pois, agora, e vê que resposta hei-de levar a quem me enviou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'Davide respondeu a Gad: Encontro-me muito perplexo, mas melhor é que eu caia nas mãos do Senhor (porque são grandes as suas misericórdias) do que nas mãos dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'Mandou, pois, o Senhor a peste a Israel, desde aquela manhã até ao tempo assinalado, morrendo do povo, desde Dan até Bersabé, setenta mil homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'Tendo estendido o anjo do Senhor a sua mão sobre Jerusalém para a destruir, o Senhor compadeceu-se da sua aflição e disse ao anjo exterminador do povo: Basta, detém agora a tua mão. O anjo do Senhor estava junto da eira de Areuna Jebuseu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'Davide, logo que viu o anjo ferindo o povo, disse ao Senhor: Eu sou o que pequei, eu fui o que procedi mal; que fizeram estes, que são as ovelhas? Volte-se, te peço, a tua mão contra mim, e contra a casa de meu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'Gad foi naquele dia ter com Davide, e disse-lhe: Vai, e levanta um altar ao Senhor na eira de Areuna Jebuseu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 19, 'E Davide foi, conforme o que Gad lhe tinha dito, por ordem do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'Tendo Areuna levantado os olhos, viu que vinham para ele o rei e os seus servos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'e, adiantando-se, fez ao rei uma profunda reverência, prostrado o rosto em terra, e disse: Que motivo há para que o rei meu senhor venha a casa do seu servo? Davide respondeu-lhe: Para comprar a tua eira e edificar nela um altar ao Senhor, para que cesse a mortandade que grassa no povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'Areuna disse a Davide: Tome-a o rei meu senhor, e sacrifique como bem lhe parecer; eis aqui estão bois para o holocausto um carro e jugos de bois que servirão de lenha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'Areuna deu tudo ao rei. Areuna disse mais ao rei: O Senhor teu Deus receba o teu voto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'O rei respondeu-lhe: Eu não posso receber o que tu me ofereces, mas comprar-te-ei pelo que vale, e não oferecerei ao Senhor meu Deus holocaustos que me não custem nada. Comprou, pois, Davide a eira e os bois por cincoenta siclos de prata.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'Davide edificou ali um altar ao Senhor, e ofereceu holocaustos e hóstias pacíficas. O Senhor compadeceu-se da terra, e cessou o flagelo que assolava Israel.');
